  // nivel o menos; −1 si no toca ninguna.
  function hitIndex(level, values) {
    let best = -1, bd = 0.5;
    values.forEach((v, i) => { const d = Math.abs(level - v); if (d <= bd) { bd = d; best = i; } });
    return best;
  }

