        const LX = v => bx + 16 + ((v - lo) / (hi - lo)) * (bw - 32), ly = by + 68;
        p.noStroke(); p.fill(C.card); p.rect(bx, by, bw, bh, 14);
        p.noFill(); p.stroke(C.ok); p.strokeWeight(2); p.rect(bx, by, bw, bh, 14);
        if (lens < 1) return;
