        for (let c = 1; c < COLS; c++) p.line(g.x0 + c * g.cell, g.y0, g.x0 + c * g.cell, g.y0 + ROWS * g.cell);
        for (let k = 1; k < ROWS; k++) p.line(g.x0, g.y0 + k * g.cell, g.x0 + COLS * g.cell, g.y0 + k * g.cell);
