      loaded: m.ready,
      getState: () => ({ done: [...st.done] }),
      lock() { locked = true; },
      destroy: () => m.remove(),
      demo: m.demo,
      peek: () => ({ phase: a.phase, flight, rail, y, W, H, target: item() && rings()[order.indexOf(item().answer)] }),
