    solution: r => `${r.n}^(${r.num}/${r.den}) = ${prod(groupOf(r.n, r.den))}${sup(r.num)} = ${valueOf(r)}`,
    prompt: r => `Arma ${r.n} elevado a ${r.num}/${r.den}: reparte en grupos iguales y toma algunos`,
