        fitText(p, `${r.title} · ${it.kind === 'eq' ? 'toca todos los que cumplen' : 'la raíz es un solo número'}`, W / 2, 40, W - 24, 11);
        if (live) drawPill(p, C, askTxt(it), W / 2, 68, C.sun, 17);

