      peek: () => ({ phase: a.phase, cur: a.cur, lives: a.lives, W, H, pause, want: wantOf(item(), SPAN), ok: { x: btn.x + btn.w / 2, y: btn.y + btn.h / 2 }, seeds: Array.from({ length: 2 * SPAN + 1 }, (_, i) => ({ v: i - SPAN, x: X(i - SPAN), y: baseOf(item()), sel: sel.has(i - SPAN) })) }),
