    'cadena-todos': (K, p, v, f) => [[148, 46, 'lf'], [126, 74, 'la'], [106, 100, 'lg']].map(([y, r, l], k) => K.arc(130, y, r, 90, 90 + 359 * paso(f, k, 3), `${l} gr`)).join(''),
