      GEO.wedge(p, C, B[0], B[1], 26, dirBV, 180, C.coral, `${s.B}°`, 42);
      GEO.wedge(p, C, V[0], V[1], 22, dirVA, dirVB, C.mint, r.mode === 'falta' && !G.locked ? '?' : `${c}°`, 38);
