        p.stroke(C.bad); p.strokeWeight(1.5); p.drawingContext.setLineDash([3, 5]); p.line(bx, by, lx, ly); p.line(lx, ly, fx, fy); p.drawingContext.setLineDash([]);
        p.line(fx - 5, fy - 5, fx + 5, fy + 5); p.line(fx - 5, fy + 5, fx + 5, fy - 5);
