      arrowTo(X(0), X(r.a), L.y - 86, r.a < 0 ? C.coral : C.sky, 3, 6);
      TK.label(p, C, `flecha: ${m(r.a)}`, X(r.a / 2) + (r.a < 0 ? -30 : 30), L.y - 98, C.mute, 11, 80);
