//#archivo js/games/jefe-ruta.js
// El jefe final por rutas (jefes de los mundos de Álgebra desde el Taller de los Bloques; spec 2026-11-19-mundos-altos).
// Una batalla por turnos, sin reloj. El Guardián lanza un reto (una ecuación, una expresión, un problema) y la respuesta
// se arma como una ruta de pasos: en cada nivel, de abajo hacia arriba, se elige el paso que sí se justifica. Con la
// ruta completa se toca «¡Atacar!»: si todos los pasos son válidos, el Guardián pierde una barra de vida; si no, se
// pierde un corazón y el juego dice en qué nivel está el paso que falla (ese nivel se borra para repensarlo). Sin
// corazones, la fase empieza otra vez. Cada fase usa lo de una o dos lecciones del mundo.
// params = { name, color?: clave de la paleta, lives?, rounds: [{ title, attacks: [{ say, levels: [[válido, falso, falso?], …] }] }] }
// state = { done: ataques acertados }      (el paso válido se escribe primero; el juego rota el orden)

GAMES['jefe-ruta'] = (() => {
  const flat = params => params.rounds.flatMap((r, i) => r.attacks.map(a => ({ ...a, round: i })));
  const orderOf = (at, l) => {
    const n = at.levels[l].length; let h = 2166136261;
    for (const c of `${l}:${at.levels[l].join('|')}`) { h ^= c.codePointAt(0); h = Math.imul(h, 16777619) >>> 0; }
    return Array.from({ length: n }, (_, i) => (i + (h % n)) % n);
  };
  const rowsOf = lv => (lv.length === 3 && lv.some(t => t.length > 14) ? 2 : 1);
  const judge = (at, pick) => at.levels.findIndex((_, l) => pick[l] !== 0);   // −1: toda la ruta es válida
  function grade(state, params) {
    const all = flat(params);
    return { ok: (state?.done ?? 0) >= all.length, solution: all.map(a => a.levels[a.levels.length - 1][0]).map(t => (typeof mathStep === 'function' ? mathStep(t) : t)).join(' · ') };
  }

  function create(host, params, api) {
    const C = api.palette, A = flat(params), LIVES = params.lives ?? 3, tx = t => (typeof mathStep === 'function' ? mathStep(t) : t);
    let locked = false, W = 0, H = 0, phase = 'idle', ai = 0, lives = LIVES, pick = [], done = 0, wrong = -1, hurt = 0, shake = 0, msg = '', stopped = false, p5 = null;
    const at = () => A[Math.min(ai, A.length - 1)], startOf = round => A.findIndex(a => a.round === round);
    const reset = () => { pick = at().levels.map(() => -1); wrong = -1; };
    const hold = (l, k) => {
      const a = at(), top = 132, units = a.levels.reduce((t, lv) => t + rowsOf(lv), 0), u = Math.min(58, (H - 84 - top) / units), bottom = top + units * u, h = Math.min(44, u - 8);   /* la pared va pegada al reto */
      const lv = a.levels[l], rows = rowsOf(lv), below = a.levels.slice(0, l).reduce((t, x) => t + rowsOf(x), 0), y = bottom - (below + rows) * u + (u - h) / 2;
      if (rows === 2) { const w = (W - 44 - 8) / 2; return k < 2 ? { x: 32 + k * (w + 8), y, w, h } : { x: 32 + (W - 44 - w) / 2, y: y + u, w, h }; }
      const w = (W - 44 - (lv.length - 1) * 8) / lv.length;
      return { x: 32 + k * (w + 8), y, w, h };
    };
    const btn = () => ({ x: W / 2 - 76, y: H - 66, w: 152, h: 40 });
    reset();

    const m = mountSketch(host, (p, size) => {
      p5 = p;
      p.setup = () => { p.createCanvas(size.w, size.h); p.textFont('system-ui'); W = size.w; H = size.h; };
      p.onResize = () => { W = size.w; H = size.h; if (stopped) p.redraw(); };

      function boss(x, y) {
        const col = C[params.color] || C.coral, sx = shake > 0 ? Math.sin(shake * 40) * 6 * shake : 0, alive = done < A.length;
        // Un núcleo con dos anillos que giran; al recibir un golpe se apaga un instante y, vencido, queda gris.
        const t = performance.now() / 1000, on = alive ? col : C.mute;
        p.stroke(C.line); p.strokeWeight(1); p.fill(C.card); p.circle(x + sx, y, 52);
        p.noFill(); p.strokeWeight(1.6);
        for (let i = 0; i < 2; i++) { p.stroke(i ? C.sky : on); p.push(); p.translate(x + sx, y); p.rotate((alive ? t : 0) * (0.6 + i * 0.3) * (i ? -1 : 1) + i); p.ellipse(0, 0, 74 - i * 10, 20 + i * 8); p.pop(); }
        const glow = p.color(on); glow.setAlpha(hurt > 0 ? 25 : 80); p.noStroke(); p.fill(glow); p.circle(x + sx, y, 30 + (alive ? Math.sin(t * 3) * 3 : 0));
        p.fill(hurt > 0 ? C.mute : on); p.circle(x + sx, y, 13);
      }

      p.draw = () => {
        p.background(C.bg);
        const dt = frameDt(p); hurt = Math.max(0, hurt - dt * 3); shake = Math.max(0, shake - dt * 2.5);
        const a = at(), r = params.rounds[a.round];
        drawKicker(p, C, r.title, 14, 18);
        drawHearts(p, C, W - 12, 18, phase === 'idle' || phase === 'all' || locked ? LIVES : lives, LIVES);
        // Vida del Guardián: una barra por ataque.
        const bw = Math.min(22, (W - 110) / A.length);
        for (let i = 0; i < A.length; i++) { p.noStroke(); p.fill(i < A.length - done ? C.coral : C.line); p.rect(14 + i * bw, 38, bw - 4, 10, 4); }
        p.noStroke(); p.fill(C.mute); p.textStyle(p.BOLD); p.textSize(11); p.textAlign(p.LEFT, p.CENTER); p.text(params.name, 14, 62);
        boss(W - 46, 76);
        const all = locked || phase === 'all';
        if (!all) {
          // El reto y la pared de pasos.
          p.noStroke(); p.fill(C.N); p.textStyle(p.BOLD); p.textAlign(p.CENTER, p.CENTER); fitText(p, tx(a.say), (W - 84) / 2 + 6, 104, W - 100, 17, 40);
          const pts = [];
          for (let l = 0; l < a.levels.length; l++) { const k = orderOf(a, l).indexOf(pick[l]); if (pick[l] < 0 || k < 0) break; const b = hold(l, k); pts.push([b.x + b.w / 2, b.y + b.h / 2]); }
          if (pts.length > 1) { p.noFill(); p.stroke(C.sky); p.strokeWeight(4); p.beginShape(); pts.forEach(q => p.vertex(q[0], q[1])); p.endShape(); }
          a.levels.forEach((lv, l) => {
            const b0 = hold(l, 0);
            p.noStroke(); p.fill(l === wrong ? C.bad : C.mute); p.textStyle(p.BOLD); p.textSize(12); p.textAlign(p.CENTER, p.CENTER); p.text(l + 1, 18, b0.y + b0.h / 2 + (rowsOf(lv) === 2 ? (hold(l, 2).y - b0.y) / 2 : 0));
            orderOf(a, l).forEach((opt, k) => {
              const b = hold(l, k), sel = pick[l] === opt, fill = sel ? C.sky : C.cream;
              drawTile(p, C, b, '', { fill, r: 12, lift: 3, ring: sel ? C.brand : l === wrong ? C.bad : null });
              p.noStroke(); p.fill(inkOn(fill, C.ink)); p.textStyle(p.BOLD); p.textAlign(p.CENTER, p.CENTER);
              const t = lv[opt], f = tx(t), parts = typeof stepLines === 'function' ? stepLines(t) : [t];
              if (parts.length === 2 && typeof drawFormulaCtx === 'function') parts.forEach((q, j) => { const g = tx(q); if (g !== q) drawFormulaCtx(p.drawingContext, g, b.x + b.w / 2, b.y + b.h / 2 + (j ? 9 : -8), { size: 13, maxW: b.w - 10, maxH: b.h / 2 - 2, weight: 700 }); else fitText(p, q, b.x + b.w / 2, b.y + b.h / 2 + (j ? 9 : -8), b.w - 8, 12); });
              else if (f !== t && typeof drawFormulaCtx === 'function') drawFormulaCtx(p.drawingContext, f, b.x + b.w / 2, b.y + b.h / 2 + 1, { size: 15, maxW: b.w - 10, maxH: b.h - 6, weight: 700 });
              else fitText(p, t, b.x + b.w / 2, b.y + b.h / 2 + 1, b.w - 8, 13);
            });
          });
          const full = pick.every(v => v >= 0), bb = btn();
          if (phase === 'play') drawTile(p, C, bb, '¡Atacar!', { fill: full ? C.coral : C.line, ink: full ? undefined : C.mute, size: 16, r: 14 });
        }
        p.noStroke(); p.fill(C.mute); p.textStyle(p.NORMAL); p.textSize(11); p.textAlign(p.CENTER, p.CENTER);
        const mid = (150 + H - 84) / 2;
        if (all) { drawBanner(p, C, `¡Venciste ${("a " + params.name).replace(/^a el /, "al ")}!`, 'Ya puedes comprobar', mid, C.ok); }
        else if (phase === 'idle') drawBanner(p, C, 'Toca para empezar', 'Sin prisa: arma la ruta y ataca', mid);
        else if (phase === 'lost') drawBanner(p, C, 'Te quedaste sin corazones', 'Toca para repetir la fase', mid, C.coral);
        else if (phase === 'hit') drawBanner(p, C, '¡Golpe certero!', 'Toca para seguir', mid, C.ok);
        if (!all && phase === 'play') fitText(p, msg || 'Un paso por nivel, de abajo hacia arriba', W / 2, H - 14, W - 20, 11);
        if (all && !stopped) { stopped = true; p.noLoop(); }
      };

      p.mousePressed = () => {
        if (locked || phase === 'all' || !inCanvas(p)) return;
        const x = p.mouseX, y = p.mouseY;
        if (phase === 'idle' || phase === 'lost') { lives = LIVES; ai = startOf(at().round); done = ai; reset(); msg = ''; phase = 'play'; api.sfx?.tap?.(); return false; }
        if (phase === 'hit') { if (done >= A.length) { phase = 'all'; api.ready(true); } else { ai = done; reset(); msg = ''; phase = ai > 0 && A[ai].round !== A[ai - 1].round ? 'idle' : 'play'; if (phase === 'idle') lives = LIVES; } return false; }
        const a = at();
        for (let l = 0; l < a.levels.length; l++) {
          const o = orderOf(a, l), k = o.findIndex((_, j) => hitBox(hold(l, j), x, y));
          if (k >= 0) { pick[l] = pick[l] === o[k] ? -1 : o[k]; if (l === wrong) wrong = -1; api.sfx?.tap?.(); return false; }
        }
        if (hitBox(btn(), x, y) && pick.every(v => v >= 0)) {
          const bad = judge(a, pick);
          if (bad < 0) { done = ai + 1; hurt = 1; shake = 1; phase = 'hit'; api.sfx?.ok?.(); }
          else { lives--; wrong = bad; pick[bad] = -1; msg = `El paso del nivel ${bad + 1} no se justifica: piénsalo otra vez`; api.sfx?.bad?.(); if (lives <= 0) phase = 'lost'; }
          return false;
        }
      };
    }, 1.45);

    return {
      loaded: m.ready,
      getState: () => ({ done }),
      peek: () => ({ phase, ai, lives, done, total: A.length, W, H, btn: btn(), holds: at().levels.map((_, l) => orderOf(at(), l).map((opt, k) => ({ opt, ...hold(l, k) }))) }),
      lock() { locked = true; if (p5 && stopped) p5.redraw(); },
      destroy: () => m.remove(),
    };
  }
  return { grade, create, flat, judge, orderOf };
})();
;
//#archivo js/games/torre-grados.js
// La torre de grados (Álgebra, polinomios; juego dinámico de alg-23a; spec 2026-11-21-dinamicos-mundos-altos): los
// términos de un polinomio están revueltos, como los bloques de la caja de Caro. Se tocan de mayor a menor exponente
// para apilarlos: el primero que se pone dice el grado. El coeficiente no manda (un 9 pequeño va después de un x³), el
// término sin x es el de grado 0 y va de último. Tocar uno que no es el siguiente quita una vida.
// params = { rounds: [{ title, items: [{ terms: [[coeficiente, exponente], …] }] }], lives? }   state = { done: [n] }

GAMES['torre-grados'] = (() => {
  const termTex = ([c, e]) => `${c < 0 ? '-' : ''}${Math.abs(c) === 1 && e > 0 ? '' : Math.abs(c)}${e === 0 ? '' : e === 1 ? 'x' : `x^{${e}}`}`;
  const sorted = it => it.terms.map((_, i) => i).sort((a, b) => it.terms[b][1] - it.terms[a][1]);
  const polyTex = (it, idx) => idx.map((i, k) => { const t = termTex(it.terms[i]); return k === 0 ? t : t.startsWith('-') ? ` - ${t.slice(1)}` : ` + ${t}`; }).join('');
  const gradeOf = it => Math.max(...it.terms.map(t => t[1]));
  return questGame({
    aspect: 1.2,
    init: () => ({ order: [] }),
    ok: (s, it) => s.order.length === it.terms.length && s.order.join() === sorted(it).join(),
    answer: it => ({ order: sorted(it) }),
    solution: it => `$${polyTex(it, sorted(it))}$: grado ${gradeOf(it)}`,
    prompt: () => 'Apila los términos, del exponente mayor al menor',
    foot: (it, s) => (s.order.length ? 'El coeficiente no decide: mira el exponente de x' : 'El primero que pongas dice el grado'),
    layout(G) {
      const n = G.item.terms.length, cols = Math.min(3, n), w = (G.W - 24 - (cols - 1) * 10) / cols, rows = Math.ceil(n / cols), y0 = G.bottom - rows * 50 - 6;
      G.tile = i => ({ x: 12 + (i % cols) * (w + 10), y: y0 + Math.floor(i / cols) * 50, w, h: 40 });
      G.board = { x: 12, y: G.top + 6, w: G.W - 24, h: Math.max(60, y0 - G.top - 22) };
    },
    draw(G) {
      const { p, C, W, s, item: it } = G, b = G.board;
      p.noStroke(); p.fill(shade(C.card, 0.82)); p.rect(b.x, b.y + 3, b.w, b.h, 14);
      p.stroke(G.solved ? C.ok : C.line); p.strokeWeight(2); p.fill(C.card); p.rect(b.x, b.y, b.w, b.h, 14);
      p.noStroke(); p.textAlign(p.CENTER, p.CENTER); p.textStyle(p.BOLD);
      if (!s.order.length) { p.fill(C.mute); p.textStyle(p.NORMAL); fitText(p, 'Aquí queda el polinomio ordenado', W / 2, b.y + b.h / 2, b.w - 20, 13); }
      else { p.fill(C.ink); fitText(p, `$${polyTex(it, s.order)}$`, W / 2, b.y + b.h / 2 - (G.solved ? 10 : 0), b.w - 20, 20, 30); if (G.solved) { p.fill(C.ok); fitText(p, `grado ${gradeOf(it)}`, W / 2, b.y + b.h - 16, b.w - 20, 14); } }
      it.terms.forEach((t, i) => { const used = s.order.includes(i); drawTile(p, C, G.tile(i), `$${termTex(t)}$`, { fill: used ? C.line : C.cream, ink: used ? C.mute : undefined, size: 18 }); });
    },
    press(G, x, y) {
      const it = G.item, s = G.s, i = it.terms.findIndex((_, k) => !s.order.includes(k) && hitBox(G.tile(k), x, y));
      if (i < 0) return false;
      const best = Math.max(...it.terms.filter((_, k) => !s.order.includes(k)).map(t => t[1]));
      if (it.terms[i][1] !== best) { G.bad(it.terms[i][1] === 0 ? 'El número solo es de grado 0: va de último' : 'Todavía queda un exponente más alto'); return true; }
      s.order.push(i); G.api.sfx?.tap?.();
      if (s.order.length === it.terms.length) G.good(`Grado ${gradeOf(it)}`);
      return true;
    },
    peek: G => { const left = sorted(G.item).filter(i => !G.s.order.includes(i)); return { solve: left.map(i => G.tile(i)), wrong: left.length > 1 ? G.tile(left[left.length - 1]) : null }; },
  });
})();
;
//#archivo js/games/arma-la-mesa.js
// Arma la mesa (Álgebra, productos notables; juego dinámico de alg-3; spec 2026-11-21-dinamicos-mundos-altos): como
// en el video, una mesa cuadrada de lado x crece `a` por cada lado. Para completarla no basta con la esquina a²:
// hacen falta las dos tablas de a por x (el doble producto). En la bandeja hay piezas con su área; se tocan las que
// completan la mesa y luego «Listo». Sobran piezas trampa.
// params = { rounds: [{ title, items: [{ a, pieces: [áreas como texto: '3x', '9', …] }] }], lives? }   state = { done: [n] }

GAMES['arma-la-mesa'] = (() => {
  const need = it => [`${it.a}x`, `${it.a}x`, `${it.a * it.a}`];
  // Índices de las piezas que completan la mesa (las dos tablas y la esquina).
  const answerIdx = it => { const used = []; for (const t of need(it)) { const k = it.pieces.findIndex((q, i) => q === t && !used.includes(i)); used.push(k); } return used.sort((a, b) => a - b); };
  const picked = s => s.on.map((v, i) => (v ? i : -1)).filter(i => i >= 0);
  return questGame({
    aspect: 1.3,
    init: it => ({ on: it.pieces.map(() => false) }),
    ok: (s, it) => { const got = picked(s).map(i => it.pieces[i]).sort().join('|'); return got === [...need(it)].sort().join('|'); },
    answer: it => ({ on: it.pieces.map((_, i) => answerIdx(it).includes(i)) }),
    solution: it => `$(x + ${it.a})^2 = x^2 + ${2 * it.a}x + ${it.a * it.a}$`,
    prompt: it => `La mesa crece ${it.a} por lado: complétala`,
    foot: () => 'Toca las piezas que hacen falta y luego «Listo»',
    no: (it, s) => { const got = picked(s).map(i => it.pieces[i]), bars = got.filter(t => t === `${it.a}x`).length; return bars < 2 ? `Faltan tablas de ${it.a} por x` : !got.includes(`${it.a * it.a}`) ? 'Falta la esquina' : 'Sobra una pieza que no cabe'; },
    layout(G) {
      const n = G.item.pieces.length, cols = Math.min(4, n), w = (G.W - 24 - (cols - 1) * 8) / cols, rows = Math.ceil(n / cols), y0 = G.bottom - 46 - rows * 46;
      G.tile = i => ({ x: 12 + (i % cols) * (w + 8), y: y0 + Math.floor(i / cols) * 46, w, h: 38 });
      G.btn = { x: G.W / 2 - 60, y: G.bottom - 40, w: 120, h: 34 };
      G.area = { y: G.top + 4, h: y0 - G.top - 14 };
    },
    draw(G) {
      const { p, C, W, s, item: it } = G, got = picked(s).map(i => it.pieces[i]);
      // Lo elegido se pone en la mesa tal cual, encaje o no: el juego no avisa cuál pieza es la buena antes de «Listo».
      const xs = got.filter(t => /x$/.test(t)), nums = got.filter(t => !/x$/.test(t));
      const side = Math.min(G.area.h - 22, W - 120), X = side * 0.68, a = side - X, x0 = W / 2 - side / 2, y0 = G.area.y + 20;
      p.noStroke(); p.fill(C.sky); p.rect(x0, y0, X - 2, X - 2, 4);
      p.fill(inkOn(C.sky, C.ink)); p.textStyle(p.BOLD); p.textAlign(p.CENTER, p.CENTER); fitText(p, '$x^2$', x0 + X / 2, y0 + X / 2, X - 8, 18);
      const part = (x, y, w, h, on, col, txt) => {
        if (on) { p.noStroke(); p.fill(col); p.rect(x, y, w - 2, h - 2, 4); p.fill(inkOn(col, C.ink)); p.textStyle(p.BOLD); fitText(p, txt, x + w / 2, y + h / 2, w - 4, 13); }
        else { p.noFill(); p.stroke(C.mute); p.strokeWeight(1.5); p.drawingContext.setLineDash([4, 4]); p.rect(x, y, w - 2, h - 2, 4); p.drawingContext.setLineDash([]); }
      };
      part(x0 + X, y0, a, X, xs.length >= 1, C.mint, `$${xs[0]}$`); part(x0, y0 + X, X, a, xs.length >= 2, C.mint, `$${xs[1]}$`); part(x0 + X, y0 + X, a, a, nums.length >= 1, C.sun, nums[0]);
      p.noStroke(); p.fill(C.mute); p.textStyle(p.BOLD); fitText(p, `$x + ${it.a}$`, x0 + side / 2, y0 - 11, W - 40, 13);
      it.pieces.forEach((t, i) => drawTile(p, C, G.tile(i), `$${t}$`, { fill: s.on[i] ? C.mint : C.cream, size: 16, ring: s.on[i] ? C.ok : null }));
      drawBtn(p, C, G.btn, 'Listo', G.solved, G.solved ? C.ok : C.coral);
    },
    press(G, x, y) {
      if (hitBox(G.btn, x, y)) { G.submit(); return true; }
      const i = G.item.pieces.findIndex((_, k) => hitBox(G.tile(k), x, y));
      if (i < 0) return false;
      G.s.on[i] = !G.s.on[i]; G.api.sfx?.tap?.();
      return true;
    },
    peek: G => { const want = answerIdx(G.item), off = G.s.on.map((v, i) => (v !== want.includes(i) ? i : -1)).filter(i => i >= 0); return { solve: [...off.map(i => G.tile(i)), G.btn], wrong: G.btn }; },
  });
})();
;
//#archivo js/games/camino-pascal.js
// Caminos de Pascal (Álgebra, binomio de Newton; juego dinámico de alg-24c; spec 2026-11-21-dinamicos-mundos-altos):
// cada número del triángulo de Pascal cuenta de cuántas maneras se llega a su casilla bajando desde la punta, un paso
// a la izquierda o a la derecha cada vez (es elegir de cuáles paréntesis sale la b). Se trazan los caminos tocando
// casilla por casilla hasta la casilla de la estrella; el juego los va contando y avisa si uno ya se había contado.
// Cuando están todos, dice el número: ese es el coeficiente. No hay vidas que perder por explorar.
// params = { rounds: [{ title, items: [{ row, k }] }], lives? }   state = { done: [n] }

GAMES['camino-pascal'] = (() => {
  const binom = (n, k) => { let v = 1; for (let i = 0; i < k; i++) v = (v * (n - i)) / (i + 1); return Math.round(v); };
  // Todos los caminos de la punta a la casilla (row, k): la posición en cada fila.
  function paths(row, k) {
    const out = [];
    (function go(path) { const r = path.length - 1, j = path[r]; if (r === row) { if (j === k) out.push(path.join('')); return; } go([...path, j]); go([...path, j + 1]); })([0]);
    return out;
  }
  return questGame({
    aspect: 1.35,
    init: () => ({ path: [0], found: [] }),
    ok: (s, it) => s.found.length === binom(it.row, it.k) && new Set(s.found).size === s.found.length,
    answer: it => ({ path: [0], found: paths(it.row, it.k) }),
    solution: it => `$C(${it.row}, ${it.k}) = ${binom(it.row, it.k)}$ caminos`,
    prompt: it => `Encuentra todos los caminos hasta la estrella`,
    foot: (it, s) => `Llevas ${s.found.length} ${s.found.length === 1 ? 'camino' : 'caminos'} · baja un paso a la izquierda o a la derecha`,
    idle: 'Sin prisa: cuenta con orden',
    layout(G) {
      const rows = G.item.row + 1, dy = Math.min(52, (G.bottom - G.top - 30) / rows), dx = Math.min(56, (G.W - 30) / rows), y0 = G.top + 26;
      G.cell = (r, j) => ({ x: G.W / 2 + (j - r / 2) * dx - 17, y: y0 + r * dy - 17, w: 34, h: 34 });
    },
    draw(G) {
      const { p, C, s, item: it } = G, c = (r, j) => { const b = G.cell(r, j); return [b.x + b.w / 2, b.y + b.h / 2]; };
      // Caminos ya contados (tenues) y el que se está trazando.
      p.noFill(); p.strokeWeight(3);
      for (const key of s.found) { p.stroke(C.line); p.beginShape(); [...key].forEach((j, r) => p.vertex(...c(r, +j))); p.endShape(); }
      p.stroke(C.sky); p.strokeWeight(5); p.beginShape(); s.path.forEach((j, r) => p.vertex(...c(r, j))); p.endShape();
      for (let r = 0; r <= it.row; r++) for (let j = 0; j <= r; j++) {
        const b = G.cell(r, j), on = s.path[r] === j, goal = r === it.row && j === it.k, last = s.path.length - 1, next = r === last + 1 && (j === s.path[last] || j === s.path[last] + 1);
        p.stroke(goal ? C.N : next ? C.sky : C.line); p.strokeWeight(goal || next ? 2.5 : 1.5); p.fill(on ? C.sky : C.card); p.circle(b.x + b.w / 2, b.y + b.h / 2, 30);
        p.noStroke(); p.fill(on ? inkOn(C.sky, C.ink) : goal ? C.N : C.mute); p.textStyle(p.BOLD); p.textSize(goal ? 15 : 12); p.textAlign(p.CENTER, p.CENTER);
        p.text(goal ? (G.solved ? binom(it.row, it.k) : '★') : r === 0 ? '▼' : '', b.x + b.w / 2, b.y + b.h / 2 + 1);
      }
    },
    press(G, x, y) {
      const it = G.item, s = G.s, r = s.path.length, last = s.path[r - 1];
      for (const j of [last, last + 1]) if (r <= it.row && hitBox(G.cell(r, j), x, y)) {
        s.path.push(j); G.api.sfx?.tap?.();
        if (s.path.length === it.row + 1) {
          const key = s.path.join('');
          if (j !== it.k) G.a.say('Ese camino llega a otra casilla', G.C.mute);
          else if (s.found.includes(key)) G.a.say('Ese camino ya lo contaste', G.C.mute);
          else { s.found.push(key); if (s.found.length === binom(it.row, it.k)) G.good(`${s.found.length} caminos: ese es el coeficiente`); else G.a.say(`Van ${s.found.length}`, G.C.Z); }
          s.path = [0];
        }
        return true;
      }
      // Tocar la punta empieza el camino de nuevo.
      if (hitBox(G.cell(0, 0), x, y)) { s.path = [0]; return true; }
      return false;
    },
    peek: G => { const left = paths(G.item.row, G.item.k).filter(k => !G.s.found.includes(k)); return { solve: left.flatMap(key => [G.cell(0, 0), ...[...key].slice(1).map((j, i) => G.cell(i + 1, +j))]) }; },
  });
})();
;
//#archivo js/games/reparte-barras.js
// Reparte las barras (Álgebra, factorización; juego dinámico de alg-24b; spec 2026-11-21-dinamicos-mundos-altos): el
// montón de Caro es un cuadrado x², unas barras y unos cuadritos. Para armar el rectángulo, las barras se reparten:
// unas a la derecha y otras abajo. El hueco de la esquina mide lo de un lado por lo del otro, y ahí tienen que caber
// justo los cuadritos. Se pasan barras de un lado a otro con las flechas; cuando el hueco se llena exacto, «Listo».
// No todo montón se arma: si ningún reparto sirve, «No se arma».
// params = { rounds: [{ title, items: [{ s (barras), p (cuadritos) }] }], lives? }   state = { done: [n] }

GAMES['reparte-barras'] = (() => {
  // El reparto que arma el rectángulo (a barras a la derecha), o −1 si ninguno sirve.
  const splitOf = it => { for (let a = 0; a <= it.s / 2; a++) if (a * (it.s - a) === it.p) return a; return -1; };
  return questGame({
    aspect: 1.35,
    init: it => ({ a: 0, none: false }),
    ok: (s, it) => (splitOf(it) < 0 ? !!s.none : !s.none && s.a * (it.s - s.a) === it.p),
    answer: it => (splitOf(it) < 0 ? { a: 0, none: true } : { a: splitOf(it), none: false }),
    solution: it => { const a = splitOf(it); return a < 0 ? `$x^2 + ${it.s}x + ${it.p}$ no se arma con enteros` : `$x^2 + ${it.s}x + ${it.p} = (x + ${a})(x + ${it.s - a})$`; },
    prompt: it => `$x^2 + ${it.s}x + ${it.p}$: arma el rectángulo`,
    foot: () => 'Pasa barras de un lado al otro hasta que el hueco se llene justo',
    no: (it, s) => (s.none ? 'Sí se arma: prueba otro reparto' : splitOf(it) < 0 ? 'Ningún reparto llena justo el hueco' : 'El hueco no queda lleno justo'),
    retry: G => { G.s.none = false; },
    layout(G) {
      const w = (G.W - 24 - 3 * 8) / 4, y = G.bottom - 40;
      G.btn = [0, 1, 2, 3].map(i => ({ x: 12 + i * (w + 8), y, w, h: 34 }));
      G.area = { y: G.top + 2, h: y - G.top - 34 };
    },
    draw(G) {
      const { p, C, W, s, item: it } = G, a = s.a, b = it.s - a, k = Math.min(13, (Math.min(G.area.h, W - 40)) / (6 + Math.max(a, b, 3))), X = 6 * k, x0 = W / 2 - (X + a * k) / 2, y0 = G.area.y + (G.area.h - (X + b * k)) / 2;
      const cell = (x, y, w, h, col) => { p.noStroke(); p.fill(col); p.rect(x + 1, y + 1, w - 2, h - 2, 3); };
      cell(x0, y0, X, X, C.sky);
      for (let i = 0; i < a; i++) cell(x0 + X + i * k, y0, k, X, C.mint);
      for (let j = 0; j < b; j++) cell(x0, y0 + X + j * k, X, k, C.mint);
      // El hueco: se llena con los cuadritos que hay; si faltan queda punteado y si sobran se apilan afuera.
      for (let i = 0; i < a; i++) for (let j = 0; j < b; j++) { const n = i * b + j; if (n < it.p) cell(x0 + X + i * k, y0 + X + j * k, k, k, C.sun); else { p.noFill(); p.stroke(C.mute); p.strokeWeight(1); p.rect(x0 + X + i * k + 1, y0 + X + j * k + 1, k - 2, k - 2, 3); } }
      const hole = a * b, diff = it.p - hole;
      p.noStroke(); p.fill(diff === 0 && hole > 0 ? C.ok : C.ink); p.textStyle(p.BOLD); p.textAlign(p.CENTER, p.CENTER);
      fitText(p, `${a} y ${b}: el hueco pide ${hole} · ${diff === 0 ? 'justo' : diff > 0 ? `sobran ${diff}` : `faltan ${-diff}`}`, W / 2, G.btn[0].y - 16, W - 20, 13);
      drawBtn(p, C, G.btn[0], '← barra', false, C.cream); drawBtn(p, C, G.btn[1], 'barra →', false, C.cream);
      drawBtn(p, C, G.btn[2], 'Listo', G.solved && !s.none, G.solved && !s.none ? C.ok : C.coral); drawBtn(p, C, G.btn[3], 'No se arma', G.solved && s.none, G.solved && s.none ? C.ok : C.sky);
    },
    press(G, x, y) {
      const s = G.s, i = G.btn.findIndex(b => hitBox(b, x, y));
      if (i < 0) return false;
      if (i === 0) s.a = Math.max(0, s.a - 1); else if (i === 1) s.a = Math.min(G.item.s, s.a + 1);
      else { s.none = i === 3; G.submit(); return true; }
      G.api.sfx?.tap?.();
      return true;
    },
    peek: G => { const a = splitOf(G.item), n = a < 0 ? 0 : a - G.s.a; return { solve: [...Array(Math.abs(n)).fill(G.btn[n > 0 ? 1 : 0]), G.btn[a < 0 ? 3 : 2]], wrong: G.btn[a < 0 ? 2 : 3] }; },
  });
})();
;
//#archivo js/games/gira-complejos.js
// Gira el complejo (Álgebra, números complejos; juego dinámico de alg-23c; spec 2026-11-21-dinamicos-mundos-altos):
// como en el video, multiplicar por i es dar un cuarto de vuelta; por −1, media vuelta; y el conjugado es reflejar en
// el eje real. Hay un complejo z en el plano y una estrella. Se llega a la estrella tocando «× i», «× (−1)» o
// «conjugado», sin pasarse del número de movimientos. «↶» deshace el último.
// params = { rounds: [{ title, items: [{ z: [a, b], w: [a, b], max }] }], lives? }   state = { done: [n] }

GAMES['gira-complejos'] = (() => {
  const OPS = [z => [-z[1], z[0]], z => [-z[0], -z[1]], z => [z[0], -z[1]]], NAMES = ['× i', '× (−1)', 'conjugado'];
  const same = (a, b) => a[0] === b[0] && a[1] === b[1];
  const cx = z => `${z[0] || (z[1] ? '' : 0)}${z[1] ? `${z[1] < 0 ? ' − ' : z[0] ? ' + ' : ''}${Math.abs(z[1]) === 1 ? '' : Math.abs(z[1])}i` : ''}`.trim().replace(/^− /, '−').replace(/-/g, '−');
  // La cadena más corta de movimientos que lleva z a w (o null si no cabe en `max`).
  function route(it) {
    let layer = [{ z: it.z, ops: [] }];
    for (let d = 0; d <= it.max; d++) {
      const hit = layer.find(n => same(n.z, it.w));
      if (hit) return hit.ops;
      layer = layer.flatMap(n => OPS.map((f, k) => ({ z: f(n.z), ops: [...n.ops, k] })));
    }
    return null;
  }
  const apply = (z, ops) => ops.reduce((q, k) => OPS[k](q), z);
  return questGame({
    aspect: 1.35,
    init: it => ({ ops: [] }),
    ok: (s, it) => s.ops.length <= it.max && same(apply(it.z, s.ops), it.w),
    answer: it => ({ ops: route(it) }),
    solution: it => `${cx(it.z)} → ${route(it).map(k => NAMES[k]).join(', ')} → ${cx(it.w)}`,
    prompt: it => `Lleva $z = ${cx(it.z).replace(/−/g, '-')}$ a la estrella en ${it.max} ${it.max === 1 ? 'movimiento' : 'movimientos'} o menos`,
    foot: (it, s) => `Movimientos: ${s.ops.length} de ${it.max}`,
    retry: G => { G.s.ops = []; },
    layout(G) {
      const w = (G.W - 24 - 3 * 8) / 4, y = G.bottom - 40;
      G.btn = [0, 1, 2, 3].map(i => ({ x: 12 + i * (w + 8), y, w, h: 34 }));
      const side = Math.min(G.W - 40, y - G.top - 16);
      G.plane = { cx: G.W / 2, cy: G.top + 6 + side / 2, u: side / 10 };
    },
    draw(G) {
      const { p, C, s, item: it } = G, { cx: ox, cy: oy, u } = G.plane, P = z => [ox + z[0] * u, oy - z[1] * u], z = apply(it.z, s.ops);
      p.stroke(C.line); p.strokeWeight(1);
      for (let i = -5; i <= 5; i++) { p.line(ox + i * u, oy - 5 * u, ox + i * u, oy + 5 * u); p.line(ox - 5 * u, oy + i * u, ox + 5 * u, oy + i * u); }
      p.stroke(C.ink); p.strokeWeight(2); p.line(ox - 5 * u, oy, ox + 5 * u, oy); p.line(ox, oy - 5 * u, ox, oy + 5 * u);
      p.noStroke(); p.fill(C.mute); p.textStyle(p.BOLD); p.textSize(10); p.textAlign(p.CENTER, p.CENTER); p.text('real', ox + 5 * u - 14, oy + 9); p.text('imaginario', ox + 30, oy - 5 * u + 6);
      // El camino recorrido, la estrella y el punto.
      let q = it.z; p.stroke(C.line); p.strokeWeight(2); p.noFill();
      for (const k of s.ops) { const n = OPS[k](q); p.line(...P(q), ...P(n)); q = n; }
      const [sx, sy] = P(it.w); p.noStroke(); p.fill(C.N); p.textSize(24); p.text('★', sx, sy + 1);
      const [zx, zy] = P(z); p.stroke(C.sky); p.strokeWeight(3); p.line(ox, oy, zx, zy);
      drawDot(p, C, zx, zy, 13, G.solved ? C.ok : C.sky);
      drawPill(p, C, cx(z), zx, zy - 20, G.solved ? C.ok : C.sky, 12);
      NAMES.forEach((t, i) => drawBtn(p, C, G.btn[i], t, false, C.cream));
      drawBtn(p, C, G.btn[3], '↶', false, C.coral);
    },
    press(G, x, y) {
      const s = G.s, it = G.item, i = G.btn.findIndex(b => hitBox(b, x, y));
      if (i < 0) return false;
      if (i === 3) { s.ops.pop(); return true; }
      s.ops.push(i); G.api.sfx?.tap?.();
      if (same(apply(it.z, s.ops), it.w)) G.good('¡Llegaste a la estrella!');
      else if (s.ops.length >= it.max) G.bad('Se acabaron los movimientos: empieza de nuevo');
      return true;
    },
    peek: G => { const r = route(G.item), pre = G.s.ops.map(() => G.btn[3]); return { solve: [...pre, ...r.map(k => G.btn[k])], wrong: G.item.max === 1 ? G.btn[OPS.findIndex((f, k) => !same(f(G.item.z), G.item.w))] : null }; },
  });
})();
;
//#archivo js/games/balanza-cajas.js
// La balanza de cajas (Álgebra, ecuaciones lineales; juego dinámico de alg-1; spec 2026-11-21-dinamicos-mundos-altos):
// la balanza de Ana. En cada platillo hay cajas cerradas iguales (cada una trae x baldosas) y baldosas sueltas. La
// regla es una sola: lo que se hace en un lado, se hace también en el otro. Se quita una suelta de cada lado, se
// quita una caja de cada lado y, cuando solo quedan cajas contra sueltas, se reparte. Pedir algo que un platillo no
// tiene (quitar una suelta donde no hay) quita una vida.
// params = { rounds: [{ title, items: [{ a, b, c, d }] }], lives? }   (a·x + b = c·x + d, con a > c y d > b)   state = { done: [n] }

GAMES['balanza-cajas'] = (() => {
  const xOf = it => (it.d - it.b) / (it.a - it.c);
  const side = (n, k) => `${n ? `${n === 1 ? '' : n}x` : ''}${n && k ? ' + ' : ''}${k || !n ? k : ''}`;
  return questGame({
    aspect: 1.3,
    init: it => ({ a: it.a, b: it.b, c: it.c, d: it.d, div: false }),
    ok: (s, it) => !!s.div && s.b === 0 && s.c === 0 && s.d / s.a === xOf(it),
    answer: it => ({ a: it.a - it.c, b: 0, c: 0, d: it.d - it.b, div: true }),
    solution: it => `$${side(it.a, it.b)} = ${side(it.c, it.d)}$: $x = ${xOf(it)}$`,
    prompt: () => 'Deja una caja sola: ¿cuántas baldosas trae?',
    foot: () => 'Lo que haces en un lado, hazlo también en el otro',
    layout(G) { const w = (G.W - 24 - 2 * 8) / 3, y = G.bottom - 44; G.btn = [0, 1, 2].map(i => ({ x: 12 + i * (w + 8), y, w, h: 38 })); G.area = { y: G.top + 4, h: y - G.top - 12 }; },
    draw(G) {
      const { p, C, W, s } = G, ay = G.area.y, base = ay + G.area.h - 34, half = W / 2;
      // Brazo y platillos.
      p.stroke(C.ink); p.strokeWeight(4); p.line(40, base, W - 40, base); p.line(half, base, half, base + 26);
      p.noStroke(); p.fill(C.ink); p.triangle(half - 14, base + 30, half + 14, base + 30, half, base + 8);
      const pan = (x0, w, boxes, loose) => {
        const bw = Math.min(40, (w - 8) / Math.max(1, boxes) - 3);
        for (let i = 0; i < boxes; i++) drawTile(p, C, { x: x0 + 4 + i * (bw + 3), y: base - 44, w: bw, h: 38 }, 'x', { fill: C.sky, size: 16, r: 6, lift: 2 });
        const cols = Math.max(1, Math.floor((w - 8) / 13));
        for (let i = 0; i < loose; i++) { p.noStroke(); p.fill(C.sun); p.rect(x0 + 4 + (i % cols) * 13, base - 58 - Math.floor(i / cols) * 13, 11, 11, 2); }
        p.noStroke(); p.fill(C.mute); p.textStyle(p.BOLD); p.textAlign(p.CENTER, p.CENTER); fitText(p, `${boxes} ${boxes === 1 ? 'caja' : 'cajas'} · ${loose} ${loose === 1 ? 'suelta' : 'sueltas'}`, x0 + w / 2, base + 14, w, 11);
      };
      pan(44, half - 60, s.a, s.b); pan(half + 16, half - 60, s.c, s.d);
      p.noStroke(); p.fill(G.solved ? C.ok : C.ink); p.textStyle(p.BOLD); p.textAlign(p.CENTER, p.CENTER);
      fitText(p, G.solved ? `$x = ${s.d / s.a}$: cada caja trae ${s.d / s.a}` : `$${side(s.a, s.b)} = ${side(s.c, s.d)}$`, W / 2, ay + 14, W - 20, 17);
      drawBtn(p, C, G.btn[0], '− 1 suelta', false, C.cream); drawBtn(p, C, G.btn[1], '− 1 caja', false, C.cream); drawBtn(p, C, G.btn[2], 'Repartir', G.solved, G.solved ? C.ok : C.coral);
    },
    press(G, x, y) {
      const s = G.s, i = G.btn.findIndex(b => hitBox(b, x, y));
      if (i < 0) return false;
      if (i === 0) { if (s.b < 1 || s.d < 1) { G.bad('Un platillo no tiene sueltas que quitar'); return true; } s.b--; s.d--; }
      else if (i === 1) { if (s.a < 1 || s.c < 1) { G.bad('Un platillo no tiene cajas que quitar'); return true; } s.a--; s.c--; }
      else { if (s.b || s.c) { G.bad('Primero deja cajas solas en un lado y sueltas solas en el otro'); return true; } s.div = true; G.good(`Cada caja trae ${s.d / s.a}`); return true; }
      G.api.sfx?.tap?.();
      return true;
    },
    peek: G => ({ solve: [...Array(G.s.b).fill(G.btn[0]), ...Array(G.s.c).fill(G.btn[1]), G.btn[2]], wrong: G.s.b || G.s.c ? G.btn[2] : null }),
  });
})();
;
//#archivo js/games/apunta-chorro.js
// Apunta el chorro (Álgebra, parábola y vértice; juego dinámico de alg-4a; spec 2026-11-21-dinamicos-mundos-altos):
// la fuente de Caro. Cada reto da la fórmula del chorro; hay que tocar en la cuadrícula el punto donde da la vuelta
// (el vértice) y luego «Lanzar»: el agua sale y, si el vértice está bien, pasa justo por la linterna. La fórmula puede
// venir armada, y = a(x − h)² + k, o sin armar (hay que completar el cuadrado o usar h = −b ÷ 2a).
// params = { rounds: [{ title, items: [{ a, h, k, std?: true }] }], lives? }   state = { done: [n] }
// La cuadrícula va de x = −5 a 5 y de y = −1 a 9.

GAMES['apunta-chorro'] = (() => {
  const sg = (v, first) => (v < 0 ? (first ? '-' : ' - ') : first ? '' : ' + ');
  const co = (c, first) => `${sg(c, first)}${Math.abs(c) === 1 ? '' : Math.abs(c)}`;
  const tex = it => {
    if (!it.std) return `y = ${it.a === 1 ? '' : it.a === -1 ? '-' : it.a}${it.h ? `(x ${it.h < 0 ? '+' : '-'} ${Math.abs(it.h)})^2` : 'x^2'}${it.k ? `${sg(it.k)}${Math.abs(it.k)}` : ''}`;
    const b = -2 * it.a * it.h, c = it.a * it.h * it.h + it.k;
    return `y = ${co(it.a, true)}x^2${b ? `${co(b)}x` : ''}${c ? `${sg(c)}${Math.abs(c)}` : ''}`;
  };
  return questGame({
    aspect: 1.4,
    init: () => ({ pt: null }),
    ok: (s, it) => !!s.pt && s.pt[0] === it.h && s.pt[1] === it.k,
    answer: it => ({ pt: [it.h, it.k] }),
    solution: it => `$${tex(it)}$: vértice $(${it.h}, ${it.k})$`,
    prompt: it => `$${tex(it)}$`,
    foot: (it, s) => (s.pt ? 'Toca «Lanzar» para soltar el agua' : 'Toca el punto donde el chorro da la vuelta'),
    no: (it, s) => (s.pt[0] !== it.h ? 'El chorro da la vuelta en otro x' : 'La altura del vértice es otra'),
    layout(G) {
      G.btn = { x: G.W / 2 - 60, y: G.bottom - 38, w: 120, h: 34 };
      const u = Math.min((G.W - 30) / 10, (G.btn.y - G.top - 16) / 10);
      G.grid = { u, x0: G.W / 2, y0: G.top + 8 + 9 * u };
      G.at = (x, y) => [G.grid.x0 + x * u, G.grid.y0 - y * u];
    },
    draw(G) {
      const { p, C, s, item: it } = G, { u } = G.grid;
      p.stroke(C.line); p.strokeWeight(1);
      for (let x = -5; x <= 5; x++) p.line(...G.at(x, -1), ...G.at(x, 9));
      for (let y = -1; y <= 9; y++) p.line(...G.at(-5, y), ...G.at(5, y));
      p.stroke(C.ink); p.strokeWeight(2); p.line(...G.at(-5, 0), ...G.at(5, 0)); p.line(...G.at(0, -1), ...G.at(0, 9));
      p.noStroke(); p.fill(C.mute); p.textStyle(p.BOLD); p.textSize(9); p.textAlign(p.CENTER, p.CENTER);
      for (let x = -4; x <= 4; x += 2) if (x) p.text(negTxt(x), G.at(x, 0)[0], G.at(x, 0)[1] + 9);
      for (let y = 2; y <= 8; y += 2) p.text(y, G.at(0, y)[0] - 9, G.at(0, y)[1]);
      if (G.solved) {   // el chorro: la parábola, recortada a la cuadrícula
        p.noFill(); p.stroke(C.sky); p.strokeWeight(3.5); p.beginShape();
        for (let x = -5; x <= 5.001; x += 0.1) { const y = it.a * (x - it.h) ** 2 + it.k; if (y >= -1 && y <= 9) p.vertex(...G.at(x, y)); }
        p.endShape();
      }
      if (s.pt) { const [x, y] = G.at(...s.pt); drawDot(p, C, x, y, 12, G.solved ? C.ok : C.sun); drawPill(p, C, `(${negTxt(s.pt[0])}, ${negTxt(s.pt[1])})`, x, y - 18, G.solved ? C.ok : C.sun, 11); }
      drawBtn(p, C, G.btn, 'Lanzar', G.solved, G.solved ? C.ok : s.pt ? C.coral : C.line);
    },
    press(G, x, y) {
      if (hitBox(G.btn, x, y)) { if (G.s.pt) G.submit(); return true; }
      const { u, x0, y0 } = G.grid, gx = Math.round((x - x0) / u), gy = Math.round((y0 - y) / u);
      if (gx < -5 || gx > 5 || gy < -1 || gy > 9) return false;
      G.s.pt = [gx, gy]; G.api.sfx?.tap?.();
      return true;
    },
    peek: G => { const q = (x, y) => { const [a, b] = G.at(x, y); return { x: a - 2, y: b - 2, w: 4, h: 4 }; }; return { solve: [q(G.item.h, G.item.k), G.btn], wrongs: [q(G.item.h + 1, G.item.k), G.btn] }; },
  });
})();
;
//#archivo js/games/donde-cae.js
// ¿Dónde cae el agua? (Álgebra, ecuaciones cuadráticas; juego dinámico de alg-4; spec 2026-11-21-dinamicos-mundos-altos):
// la boquilla de la fuente está en x = 0 y el agua solo cae hacia adelante. El agua toca el suelo donde la altura vale
// cero: en las raíces de la ecuación. Se ponen baldes en las marcas del suelo donde va a caer y luego «Abrir el agua».
// Como en el video, a veces una raíz no sirve (queda detrás de la boquilla), a veces hay una sola (raíz doble) y a
// veces el agua no toca el suelo nunca (no hay raíces reales): entonces no se pone ningún balde.
// params = { rounds: [{ title, items: [{ eq (TeX), roots: [raíces reales] }] }], lives? }   state = { done: [n] }
// Las marcas van de 1 a 8.

GAMES['donde-cae'] = (() => {
  const valid = it => [...new Set(it.roots.filter(r => r > 0))].sort((a, b) => a - b);
  const picked = s => s.on.map((v, i) => (v ? i + 1 : 0)).filter(Boolean);
  return questGame({
    aspect: 1.15,
    init: () => ({ on: Array(8).fill(false) }),
    ok: (s, it) => picked(s).join() === valid(it).join(),
    answer: it => ({ on: Array.from({ length: 8 }, (_, i) => valid(it).includes(i + 1)) }),
    solution: it => `$${it.eq}$: ${valid(it).length ? `cae en ${valid(it).join(' y ')}` : 'no cae adelante'}`,
    prompt: it => `$${it.eq}$`,
    foot: () => 'Pon un balde donde cae el agua (adelante de la boquilla) y abre',
    no: (it, s) => { const v = valid(it), g = picked(s); return g.some(x => !v.includes(x)) ? (it.roots.length ? 'Ahí la altura no vale cero' : 'Esta ecuación no tiene raíces reales: el agua no toca el suelo') : it.roots.some(r => r <= 0) && !v.length ? 'La raíz queda detrás de la boquilla' : 'Falta un balde'; },
    layout(G) {
      G.btn = { x: G.W / 2 - 74, y: G.bottom - 40, w: 148, h: 34 };
      const y = G.btn.y - 54, step = (G.W - 60) / 8;
      G.gy = y; G.mark = i => ({ x: 30 + i * step - step / 2 + 4, y: y - 30, w: step - 8, h: 50 }); G.X = i => 30 + i * step;
    },
    draw(G) {
      const { p, C, W, s, item: it } = G, y = G.gy;
      p.stroke(C.ink); p.strokeWeight(3); p.line(14, y, W - 14, y);
      // La boquilla en 0.
      p.noStroke(); p.fill(C.mute); p.rect(G.X(0) - 7, y - 22, 14, 22, 3); p.fill(C.mute); p.textStyle(p.BOLD); p.textSize(10); p.textAlign(p.CENTER, p.CENTER); p.text('0', G.X(0), y + 12);
      for (let i = 1; i <= 8; i++) {
        const x = G.X(i), on = s.on[i - 1];
        p.stroke(C.ink); p.strokeWeight(2); p.line(x, y - 5, x, y + 5);
        p.noStroke(); p.fill(on ? C.N : C.mute); p.textStyle(p.BOLD); p.textSize(11); p.text(i, x, y + 14);
        if (on) { const good = G.solved; p.fill(good ? C.ok : C.sky); p.quad(x - 12, y - 22, x + 12, y - 22, x + 8, y - 3, x - 8, y - 3); }
      }
      if (G.solved) for (const r of valid(it)) {   // el chorro hasta cada balde
        p.noFill(); p.stroke(C.sky); p.strokeWeight(3); p.beginShape();
        for (let t = 0; t <= 1.001; t += 0.05) p.vertex(G.X(0) + (G.X(r) - G.X(0)) * t, y - 22 - Math.sin(Math.PI * t) * Math.min(120, G.gy - G.top - 30));
        p.endShape();
      }
      if (G.solved && !valid(it).length) { p.noStroke(); p.fill(C.ok); p.textStyle(p.BOLD); fitText(p, it.roots.length ? 'La raíz queda detrás: ningún balde' : 'Sin raíces reales: ningún balde', W / 2, G.top + 30, W - 20, 14); }
      drawBtn(p, C, G.btn, 'Abrir el agua', G.solved, G.solved ? C.ok : C.coral);
    },
    press(G, x, y) {
      if (hitBox(G.btn, x, y)) { G.submit(); return true; }
      for (let i = 1; i <= 8; i++) if (hitBox(G.mark(i), x, y)) { G.s.on[i - 1] = !G.s.on[i - 1]; G.api.sfx?.tap?.(); return true; }
      return false;
    },
    peek: G => { const v = valid(G.item), off = G.s.on.map((on, i) => (on !== v.includes(i + 1) ? i + 1 : 0)).filter(Boolean); return { solve: [...off.map(i => G.mark(i)), G.btn], wrongs: [G.mark(v.includes(8) ? 7 : 8), G.btn] }; },
  });
})();
;
//#archivo js/games/empaca-filas.js
// Empaca en filas (Álgebra, división de polinomios; juego dinámico de alg-23b; spec 2026-11-21-dinamicos-mundos-altos):
// dividir es empacar, como los caramelos en bolsas del video. Aquí se empaca un montón de bloques (un cuadrado x²,
// barras x y cuadritos) en filas de ancho x + a. Una fila de alto x gasta el cuadrado y a barras; una fila de alto 1
// gasta una barra y a cuadritos. Cuando ya no se puede armar otra fila completa, «Listo»: las filas dicen el cociente
// y lo que sobra es el residuo (siempre más pequeño que una fila). Pedir una fila sin tener las piezas quita una vida.
// params = { rounds: [{ title, items: [{ a, s, p }] }], lives? }   ((x² + s·x + p) ÷ (x + a), con s ≥ a y p ≥ a(s − a))
// state = { done: [n] }

GAMES['empaca-filas'] = (() => {
  const quot = it => it.s - it.a, rest = it => it.p - it.a * (it.s - it.a);
  return questGame({
    aspect: 1.35,
    init: it => ({ sq: 1, bars: it.s, units: it.p, big: 0, small: 0, end: false }),
    ok: (s, it) => !!s.end && s.sq === 0 && s.bars === 0 && s.small === quot(it) && s.units === rest(it),
    answer: it => ({ sq: 0, bars: 0, units: rest(it), big: 1, small: quot(it), end: true }),
    solution: it => `$(x^2 + ${it.s}x + ${it.p}) \\div (x + ${it.a})$: cociente $x + ${quot(it)}$, residuo ${rest(it)}`,
    prompt: it => `Empaca $x^2 + ${it.s}x + ${it.p}$ en filas de ancho $x + ${it.a}$`,
    foot: () => 'Una fila completa necesita todas sus piezas; lo que no alcance, sobra',
    layout(G) { const w = (G.W - 24 - 2 * 8) / 3, y = G.bottom - 44; G.btn = [0, 1, 2].map(i => ({ x: 12 + i * (w + 8), y, w, h: 38 })); G.area = { y: G.top + 4, h: y - G.top - 34 }; },
    draw(G) {
      const { p, C, W, s, item: it } = G, k = Math.min(13, G.area.h / (6 + Math.max(4, quot(it) + 1)), (W - 150) / (6 + it.a)), X = 6 * k, x0 = 16, y0 = G.area.y + 4;
      const cell = (x, y, w, h, col) => { p.noStroke(); p.fill(col); p.rect(x + 1, y + 1, w - 2, h - 2, 3); };
      // Las filas ya empacadas (a la izquierda).
      if (s.big) { cell(x0, y0, X, X, C.sky); for (let i = 0; i < it.a; i++) cell(x0 + X + i * k, y0, k, X, C.mint); }
      for (let j = 0; j < s.small; j++) { cell(x0, y0 + (s.big ? X : 0) + j * k, X, k, C.mint); for (let i = 0; i < it.a; i++) cell(x0 + X + i * k, y0 + (s.big ? X : 0) + j * k, k, k, C.sun); }
      p.noFill(); p.stroke(C.mute); p.strokeWeight(1.5); p.drawingContext.setLineDash([4, 4]); p.rect(x0, y0, X + it.a * k, Math.max(X, (s.big ? X : 0) + s.small * k), 4); p.drawingContext.setLineDash([]);
      p.noStroke(); p.fill(C.mute); p.textStyle(p.BOLD); p.textAlign(p.CENTER, p.CENTER); fitText(p, `ancho $x + ${it.a}$`, x0 + (X + it.a * k) / 2, y0 + Math.max(X, (s.big ? X : 0) + s.small * k) + 12, X + it.a * k + 30, 12);
      // Lo que queda sin empacar (a la derecha).
      const rx = W - 118, rows = [[`${s.sq}`, 'cuadrado x²', C.sky], [`${s.bars}`, 'barras x', C.mint], [`${s.units}`, 'cuadritos', C.sun]];
      p.fill(C.mute); p.textSize(11); p.textAlign(p.LEFT, p.CENTER); p.text('Quedan:', rx, y0 + 8);
      rows.forEach(([n, t, col], i) => { const y = y0 + 30 + i * 26; p.noStroke(); p.fill(col); p.rect(rx, y - 9, 18, 18, 4); p.fill(C.ink); p.textStyle(p.BOLD); p.textSize(13); p.textAlign(p.LEFT, p.CENTER); p.text(`${n} ${t}`, rx + 24, y); });
      p.fill(G.solved ? C.ok : C.ink); p.textStyle(p.BOLD); p.textAlign(p.CENTER, p.CENTER);
      fitText(p, G.solved ? `Cociente $x + ${quot(it)}$ · residuo ${rest(it)}` : `Filas: ${s.big ? `una de alto $x$` : 'ninguna de alto x'} y ${s.small} de alto 1`, W / 2, G.btn[0].y - 16, W - 20, 13);
      drawBtn(p, C, G.btn[0], 'Fila de alto x', false, C.cream); drawBtn(p, C, G.btn[1], 'Fila de alto 1', false, C.cream); drawBtn(p, C, G.btn[2], 'Listo', G.solved, G.solved ? C.ok : C.coral);
    },
    press(G, x, y) {
      const s = G.s, it = G.item, i = G.btn.findIndex(b => hitBox(b, x, y));
      if (i < 0) return false;
      if (i === 0) { if (!s.sq) { G.bad('Ya no hay cuadrado para una fila de alto x'); return true; } if (s.bars < it.a) { G.bad('No alcanzan las barras para esa fila'); return true; } s.sq = 0; s.bars -= it.a; s.big = 1; }
      else if (i === 1) { if (s.sq) { G.bad('Empieza por lo más grande: la fila de alto x'); return true; } if (s.bars < 1) { G.bad('Ya no quedan barras: lo demás es el residuo'); return true; } if (s.units < it.a) { G.bad('No alcanzan los cuadritos para otra fila'); return true; } s.bars--; s.units -= it.a; s.small++; }
      else { if (s.sq || s.bars) { G.bad('Todavía se puede armar otra fila'); return true; } s.end = true; G.good(`Sobran ${s.units}: es el residuo`); return true; }
      G.api.sfx?.tap?.();
      return true;
    },
    peek: G => ({ solve: [...(G.s.sq ? [G.btn[0]] : []), ...Array(G.s.bars - (G.s.sq ? G.item.a : 0)).fill(G.btn[1]), G.btn[2]], wrong: G.s.sq || G.s.bars ? G.btn[2] : null }),
  });
})();
;
//#archivo js/games/sondea-niebla.js
// Sondea la niebla (Álgebra, teorema del residuo y del factor; juego dinámico de alg-92; spec
// 2026-11-21-dinamicos-mundos-altos): la cordillera está tapada por la niebla, como en la apuesta de Beto. La altura
// del terreno en x es P(x) (el residuo de dividir entre x − x). Con una linterna se ve la altura en un punto; hay
// pocas linternas. Donde la altura es 0, la vía cruza: ahí va una bandera. No hace falta alumbrar todo: si en un
// punto el terreno está arriba de la vía y en otro abajo, entre los dos hay un cruce (todos los cruces son enteros).
// Se cambia entre «Linterna» y «Bandera» con los botones y se toca la columna. «Listo» comprueba las banderas.
// params = { rounds: [{ title, items: [{ roots: [enteros distintos entre −4 y 4], a: 1 | −1, lamps? }] }], lives? }
// state = { done: [n] }

GAMES['sondea-niebla'] = (() => {
  const f = (it, x) => it.a * it.roots.reduce((t, r) => t * (x - r), 1);
  const lampsOf = it => it.lamps ?? 5;
  const sortN = a => [...a].sort((x, y) => x - y);
  return questGame({
    aspect: 1.3,
    init: () => ({ seen: [], flags: [], flag: false }),
    ok: (s, it) => sortN(s.flags).join() === sortN(it.roots).join(),
    answer: it => ({ seen: [], flags: sortN(it.roots), flag: true }),
    solution: it => `Cruces en ${sortN(it.roots).map(negTxt).join(', ')}: $P(x) = ${it.a < 0 ? '-' : ''}${sortN(it.roots).map(r => `(x ${r < 0 ? '+' : '-'} ${Math.abs(r)})`).join('').replace(/\(x - 0\)/, 'x')}$`,
    prompt: it => `La vía cruza ${it.roots.length} veces: pon las banderas`,
    foot: (it, s) => (s.flag ? 'Toca una columna para poner o quitar una bandera' : `Linternas: ${lampsOf(it) - s.seen.length} · arriba y abajo de la vía: hay un cruce en medio`),
    no: () => 'Las banderas no están en los cruces',
    layout(G) {
      const w = (G.W - 24 - 2 * 8) / 3, y = G.bottom - 42; G.btn = [0, 1, 2].map(i => ({ x: 12 + i * (w + 8), y, w, h: 36 }));
      const cw = (G.W - 24) / 9, top = G.top + 8, h = y - top - 26;
      G.col = x => ({ x: 12 + (x + 4) * cw, y: top, w: cw, h }); G.mid = top + h / 2; G.amp = h / 2 - 12;
    },
    draw(G) {
      const { p, C, W, s, item: it } = G, scale = v => Math.max(-1, Math.min(1, v / 12)) * G.amp;
      p.stroke(C.ink); p.strokeWeight(3); p.line(12, G.mid, W - 12, G.mid);
      for (let x = -4; x <= 4; x++) {
        const b = G.col(x), cx = b.x + b.w / 2, v = f(it, x), seen = s.seen.includes(x) || G.solved;
        p.noStroke(); p.fill(C.mute); p.textStyle(p.BOLD); p.textSize(10); p.textAlign(p.CENTER, p.CENTER); p.text(negTxt(x), cx, b.y + b.h + 9);
        if (seen) {
          if (v === 0) { p.fill(C.N); p.circle(cx, G.mid, 11); }
          else { p.fill(v > 0 ? C.mint : C.coral); p.rect(cx - 7, v > 0 ? G.mid - scale(v) : G.mid, 14, Math.abs(scale(v)), 3); p.fill(C.ink); p.textSize(10); p.text(negTxt(v), cx, v > 0 ? G.mid - scale(v) - 8 : G.mid - scale(v) + 8); }
        } else { p.fill(C.line); p.circle(cx - 5, G.mid - 14, 22); p.circle(cx + 6, G.mid - 4, 20); p.circle(cx - 3, G.mid + 12, 22); }
        if (s.flags.includes(x)) { p.stroke(C.ink); p.strokeWeight(2); p.line(cx, G.mid, cx, G.mid - 30); p.noStroke(); p.fill(G.solved ? C.ok : C.coral); p.triangle(cx, G.mid - 30, cx + 13, G.mid - 24, cx, G.mid - 18); }
      }
      drawBtn(p, C, G.btn[0], `Linterna (${lampsOf(it) - s.seen.length})`, !s.flag, !s.flag ? C.sun : C.cream);
      drawBtn(p, C, G.btn[1], 'Bandera', s.flag, s.flag ? C.sun : C.cream);
      drawBtn(p, C, G.btn[2], 'Listo', G.solved, G.solved ? C.ok : C.coral);
    },
    press(G, x, y) {
      const s = G.s, it = G.item, i = G.btn.findIndex(b => hitBox(b, x, y));
      if (i === 0 || i === 1) { s.flag = i === 1; return true; }
      if (i === 2) { G.submit(); return true; }
      for (let c = -4; c <= 4; c++) if (hitBox(G.col(c), x, y)) {
        if (s.flag) { const k = s.flags.indexOf(c); if (k >= 0) s.flags.splice(k, 1); else s.flags.push(c); }
        else if (!s.seen.includes(c)) { if (s.seen.length >= lampsOf(it)) { G.a.say('Ya no quedan linternas: razona con lo que viste', G.C.mute); return true; } s.seen.push(c); }
        G.api.sfx?.tap?.();
        return true;
      }
      return false;
    },
    peek: G => { const it = G.item, s = G.s, diff = [-4, -3, -2, -1, 0, 1, 2, 3, 4].filter(x => s.flags.includes(x) !== it.roots.includes(x)); return { solve: [...(s.flag ? [] : [G.btn[1]]), ...diff.map(x => { const b = G.col(x); return { x: b.x + b.w / 2 - 2, y: G.mid - 2, w: 4, h: 4 }; }), G.btn[2]], wrong: G.btn[2] }; },
  });
})();
;
//#archivo js/games/cruza-o-rebota.js
// ¿Cruza o rebota? (Álgebra, ceros y multiplicidad; juego dinámico de alg-93; spec 2026-11-21-dinamicos-mundos-altos):
// la montaña del video cruza la vía en unos ceros y en otros la toca y se devuelve. Eso lo decide cuántas veces se
// repite el factor: repetido un número impar de veces, cruza; un número par, rebota. Cada reto da el polinomio
// factorizado; en cada cero se toca la ficha para elegir «cruza» o «rebota» y luego «Dibujar»: el juego traza la
// montaña y se ve si quedó como se dijo.
// params = { rounds: [{ title, items: [{ a: 1 | −1, factors: [[cero, veces], …] }] }], lives? }   state = { done: [n] }

GAMES['cruza-o-rebota'] = (() => {
  const want = it => it.factors.map(([, m]) => (m % 2 ? 'c' : 'r'));
  const tex = it => `y = ${it.a < 0 ? '-' : ''}${it.factors.map(([r, m]) => `${r === 0 ? 'x' : `(x ${r < 0 ? '+' : '-'} ${Math.abs(r)})`}${m > 1 ? `^{${m}}` : ''}`).join('')}`;
  const f = (it, x) => it.a * it.factors.reduce((t, [r, m]) => t * (x - r) ** m, 1);
  return questGame({
    aspect: 1.25,
    init: it => ({ pick: it.factors.map(() => '') }),
    ok: (s, it) => s.pick.join() === want(it).join(),
    answer: it => ({ pick: want(it) }),
    solution: it => `$${tex(it)}$: ${it.factors.map(([r, m]) => `en ${negTxt(r)} ${m % 2 ? 'cruza' : 'rebota'}`).join(', ')}`,
    prompt: it => `$${tex(it)}$`,
    foot: () => 'Mira cuántas veces se repite cada factor',
    no: (it, s) => (s.pick.includes('') ? 'Falta decidir un cero' : 'Mira el exponente del factor: impar cruza, par rebota'),
    layout(G) {
      G.btn = { x: G.W / 2 - 60, y: G.bottom - 38, w: 120, h: 34 };
      const top = G.top + 6, h = G.btn.y - top - 60;
      G.X = x => 20 + (x + 5) * (G.W - 40) / 10; G.mid = top + h / 2; G.amp = h / 2 - 6;
      G.chip = i => { const x = G.X(G.item.factors[i][0]), w = Math.min(78, 2 * (G.W - 40) / 10 - 6); return { x: Math.max(8, Math.min(G.W - 8 - w, x - w / 2)), y: G.btn.y - 50, w, h: 34 }; };   // ceros a 2 unidades no se enciman
    },
    draw(G) {
      const { p, C, W, s, item: it } = G;
      p.stroke(C.ink); p.strokeWeight(3); p.line(12, G.mid, W - 12, G.mid);
      if (G.solved) {   // la montaña, con la altura comprimida para que quepa
        let max = 1; for (let x = -5; x <= 5; x += 0.1) max = Math.max(max, Math.abs(f(it, x)));
        const sq = v => Math.sign(v) * Math.sqrt(Math.abs(v) / max);
        p.noFill(); p.stroke(C.sky); p.strokeWeight(3.5); p.beginShape(); for (let x = -5; x <= 5.001; x += 0.05) p.vertex(G.X(x), G.mid - sq(f(it, x)) * G.amp); p.endShape();
      }
      it.factors.forEach(([r], i) => {
        const x = G.X(r), b = G.chip(i), v = s.pick[i];
        p.noStroke(); p.fill(C.N); p.circle(x, G.mid, 12);
        p.fill(C.mute); p.textStyle(p.BOLD); p.textSize(11); p.textAlign(p.CENTER, p.CENTER); p.text(negTxt(r), x, G.mid + 16);
        p.stroke(C.line); p.strokeWeight(1.5); p.line(x, G.mid + 24, b.x + b.w / 2, b.y);
        drawTile(p, C, b, v === 'c' ? 'cruza' : v === 'r' ? 'rebota' : '¿?', { fill: v ? (G.solved ? C.ok : C.sky) : C.cream, size: 14 });
      });
      drawBtn(p, C, G.btn, 'Dibujar', G.solved, G.solved ? C.ok : C.coral);
    },
    press(G, x, y) {
      if (hitBox(G.btn, x, y)) { G.submit(); return true; }
      const i = G.item.factors.findIndex((_, k) => hitBox(G.chip(k), x, y));
      if (i < 0) return false;
      G.s.pick[i] = G.s.pick[i] === 'c' ? 'r' : 'c'; G.api.sfx?.tap?.();
      return true;
    },
    peek: G => { const w = want(G.item), taps = []; G.s.pick.forEach((v, i) => { const n = v === w[i] ? 0 : v === '' ? (w[i] === 'c' ? 1 : 2) : 1; for (let k = 0; k < n; k++) taps.push(G.chip(i)); }); return { solve: [...taps, G.btn], wrong: G.btn }; },
  });
})();
;
//#archivo js/games/rio-o-hueco.js
// ¿Río o hueco? (Álgebra, dominio de una expresión racional; juego dinámico de alg-25a; spec
// 2026-11-21-dinamicos-mundos-altos): Beto camina por el sendero de una fracción, un paso entero a la vez. Antes de
// cada paso se decide qué hay en el siguiente punto: si el denominador no es cero, se camina; si arriba y abajo se
// anulan a la vez (un factor común), es un hueco y se salta; si solo se anula el denominador, es un río (una
// asíntota) y no se puede pasar: ahí termina la caminata. Equivocarse quita una vida.
// params = { rounds: [{ title, items: [{ top: [ceros del numerador], bottom: [ceros del denominador], from, to }] }], lives? }
// state = { done: [n] }      (la fracción es ∏(x − t) ÷ ∏(x − b), ya factorizada)

GAMES['rio-o-hueco'] = (() => {
  const fac = r => (r === 0 ? 'x' : `(x ${r < 0 ? '+' : '-'} ${Math.abs(r)})`);
  const tex = it => `\\frac{${it.top.map(fac).join('') || '1'}}{${it.bottom.map(fac).join('')}}`;
  // Qué hay en x: 0 camino, 1 hueco, 2 río.
  const at = (it, x) => (!it.bottom.includes(x) ? 0 : it.top.includes(x) ? 1 : 2);
  // Hasta dónde llega la caminata: el primer río, o el final del sendero.
  const endOf = it => { for (let x = it.from + 1; x <= it.to; x++) if (at(it, x) === 2) return x; return it.to; };
  const NAMES = ['Caminar', 'Saltar el hueco', 'Es un río'];
  return questGame({
    aspect: 1.2,
    init: it => ({ x: it.from, end: false }),
    ok: (s, it) => !!s.end && s.x === endOf(it),
    answer: it => ({ x: endOf(it), end: true }),
    solution: it => `$${tex(it)}$: ${it.bottom.map(b => `en ${negTxt(b)} ${at(it, b) === 1 ? 'hay un hueco' : 'hay un río'}`).join(' y ')}`,
    prompt: it => `$${tex(it)}$`,
    foot: (it, s) => `Beto está en x = ${negTxt(s.x)}: ¿qué hay en x = ${negTxt(Math.min(it.to, s.x + 1))}?`,
    layout(G) {
      const w = (G.W - 24 - 2 * 8) / 3, y = G.bottom - 44; G.btn = [0, 1, 2].map(i => ({ x: 12 + i * (w + 8), y, w, h: 38 }));
      G.py = G.top + (y - G.top) / 2; G.X = x => 24 + (x - G.item.from) * (G.W - 48) / (G.item.to - G.item.from);
    },
    draw(G) {
      const { p, C, s, item: it } = G, y = G.py;
      for (let x = it.from; x <= it.to; x++) {
        const px = G.X(x), known = x <= s.x || (s.end && x === s.x), k = at(it, x);
        if (x < it.to) { p.stroke(known && x < s.x ? C.sky : C.line); p.strokeWeight(5); p.line(px, y, G.X(x + 1), y); }
        p.noStroke();
        if (known && k === 1) { p.fill(C.bg); p.circle(px, y, 18); p.noFill(); p.stroke(C.N); p.strokeWeight(2); p.circle(px, y, 14); }
        else if (known && k === 2) { p.fill(C.Z); p.rect(px - 9, y - 40, 18, 80, 8); }
        else { p.fill(known ? C.sky : C.card); p.stroke(C.line); p.strokeWeight(1.5); p.circle(px, y, 12); }
        p.noStroke(); p.fill(C.mute); p.textStyle(p.BOLD); p.textSize(11); p.textAlign(p.CENTER, p.CENTER); p.text(negTxt(x), px, y + 22);
        if (known && k) { p.fill(k === 1 ? C.N : C.Z); p.textSize(10); p.text(k === 1 ? 'hueco' : 'río', px, y + 52); }
      }
      const bx = G.X(s.x) - (s.end && at(it, s.x) === 2 ? 20 : 0);   // Beto se queda en la orilla del río
      p.noStroke(); p.fill(C.coral); p.circle(bx, y - 24, 16); p.rect(bx - 6, y - 16, 12, 16, 4);
      NAMES.forEach((t, i) => drawBtn(p, C, G.btn[i], t, false, i === 0 ? C.cream : i === 1 ? C.sun : C.sky));
    },
    press(G, x, y) {
      const s = G.s, it = G.item, i = G.btn.findIndex(b => hitBox(b, x, y));
      if (i < 0) return false;
      const nx = s.x + 1, k = at(it, nx);
      if (i !== k) { G.bad(k === 0 ? `En x = ${negTxt(nx)} el denominador no es cero: se camina` : k === 1 ? `En x = ${negTxt(nx)} arriba también da cero: es un hueco` : `En x = ${negTxt(nx)} solo se anula abajo: es un río`); return true; }
      s.x = nx; G.api.sfx?.tap?.();
      if (k === 2) { s.end = true; G.good('Un río: hasta aquí llega el sendero'); } else if (nx === it.to) { s.end = true; G.good('¡Llegó al final del sendero!'); }
      return true;
    },
    peek: G => { const it = G.item, seq = []; for (let x = G.s.x + 1; x <= endOf(it); x++) seq.push(G.btn[at(it, x)]); return { solve: seq, wrong: G.btn[(at(it, G.s.x + 1) + 1) % 3] }; },
  });
})();
;
//#archivo js/games/llena-estanque.js
// Llena el estanque (Álgebra, suma de fracciones algebraicas; juego dinámico de alg-25b; spec
// 2026-11-21-dinamicos-mundos-altos): como Ana y Beto en el video, dos llaves llenan un estanque; una sola tarda p
// horas y la otra q. Para sumar lo que llenan por hora (1/p y 1/q) hace falta un denominador común: se parte el
// estanque en n partes iguales con − y +. Si n sirve para las dos llaves, «+ 1 hora» echa lo de las dos juntas. Cuando
// el estanque queda lleno justo, «Listo»: las horas que pasaron son la respuesta. Con un n que no sirve, o si se
// rebosa, se pierde una vida.
// params = { rounds: [{ title, items: [{ p, q }] }], lives? }   state = { done: [n] }

GAMES['llena-estanque'] = (() => {
  const gcd = (a, b) => (b ? gcd(b, a % b) : a), lcm = (a, b) => (a * b) / gcd(a, b);
  const hoursOf = it => { const n = lcm(it.p, it.q); return n / (n / it.p + n / it.q); };
  const fits = (it, n) => n % it.p === 0 && n % it.q === 0;
  return questGame({
    aspect: 1.3,
    init: it => ({ n: Math.min(it.p, it.q), h: 0, fill: 0, end: false }),
    ok: (s, it) => !!s.end && fits(it, s.n) && s.fill === s.n && s.h === hoursOf(it),
    answer: it => ({ n: lcm(it.p, it.q), h: hoursOf(it), fill: lcm(it.p, it.q), end: true }),
    solution: it => `$\\frac{1}{${it.p}} + \\frac{1}{${it.q}} = \\frac{${lcm(it.p, it.q) / it.p + lcm(it.p, it.q) / it.q}}{${lcm(it.p, it.q)}}$ por hora: juntas tardan ${hoursOf(it)} horas`,
    prompt: it => `Una llave tarda ${it.p} horas y la otra ${it.q}. ¿Y juntas?`,
    foot: () => 'Elige en cuántas partes medir el estanque y deja pasar las horas',
    retry: G => { G.s.h = 0; G.s.fill = 0; },
    layout(G) {
      const y = G.bottom - 42, w = (G.W - 36 - 150) / 2;
      G.box = { x: 12, y, w: 150, h: 34 }; G.btn = [{ x: 170, y: y - 2, w, h: 38 }, { x: 178 + w, y: y - 2, w, h: 38 }];
      G.tank = { x: 26, y: G.top + 8, w: 92, h: y - G.top - 40 };
    },
    draw(G) {
      const { p, C, W, s, item: it } = G, t = G.tank, ok = fits(it, s.n), ph = t.h / s.n;
      p.noStroke(); p.fill(G.solved ? C.ok : C.sky); p.rect(t.x, t.y + t.h - Math.min(s.n, s.fill) * ph, t.w, Math.min(s.n, s.fill) * ph);
      p.stroke(C.line); p.strokeWeight(1); for (let i = 1; i < s.n; i++) p.line(t.x, t.y + i * ph, t.x + t.w, t.y + i * ph);
      p.noFill(); p.stroke(C.ink); p.strokeWeight(3); p.line(t.x, t.y, t.x, t.y + t.h); p.line(t.x, t.y + t.h, t.x + t.w, t.y + t.h); p.line(t.x + t.w, t.y + t.h, t.x + t.w, t.y);
      const lx = t.x + t.w + 14, lw = W - lx - 10, row = (txt, y, col) => { p.noStroke(); p.fill(col); p.textStyle(p.BOLD); p.textAlign(p.LEFT, p.CENTER); fitText(p, txt, lx, y, lw, 13, 30); };
      row(`Estanque en ${s.n} partes`, t.y + 12, C.ink);
      // Lo que llena cada llave en partes del estanque solo se ve después de dejar pasar una hora: así no se
      // encuentra el denominador común subiendo n hasta que el renglón cambie.
      const seen = ok && s.h > 0;
      row(seen ? `Llave 1: $\\frac{${s.n / it.p}}{${s.n}}$ por hora` : `Llave 1: $\\frac{1}{${it.p}}$ por hora`, t.y + 46, seen ? C.Z : C.mute);
      row(seen ? `Llave 2: $\\frac{${s.n / it.q}}{${s.n}}$ por hora` : `Llave 2: $\\frac{1}{${it.q}}$ por hora`, t.y + 84, seen ? C.Z : C.mute);
      row(`Horas: ${s.h}`, t.y + 122, C.ink);
      row(G.solved ? `Juntas: ${s.h} horas` : `Lleno: $\\frac{${s.fill}}{${s.n}}$`, t.y + 152, G.solved ? C.ok : C.N);
      drawStepper(p, C, G.box, s.n, 'partes', C.Z);
      drawBtn(p, C, G.btn[0], '+ 1 hora', false, C.cream); drawBtn(p, C, G.btn[1], 'Listo', G.solved, G.solved ? C.ok : C.coral);
    },
    press(G, x, y) {
      const s = G.s, it = G.item, d = stepHit(G.box, x, y);
      if (d) { s.n = Math.max(2, Math.min(30, s.n + d)); s.h = 0; s.fill = 0; G.api.sfx?.tap?.(); return true; }
      if (hitBox(G.btn[0], x, y)) {
        if (!fits(it, s.n)) { G.bad(`Con ${s.n} partes no se puede medir lo que llena cada llave en una hora`); return true; }
        if (s.fill >= s.n) { G.bad('Ya está lleno: una hora más y se rebosa'); return true; }
        s.h++; s.fill += s.n / it.p + s.n / it.q; G.api.sfx?.tap?.();
        if (s.fill > s.n) G.bad('Se rebosó: sobraba menos de una hora');
        return true;
      }
      if (hitBox(G.btn[1], x, y)) { s.end = true; if (!G.submit(s.fill < s.n ? 'Todavía no está lleno' : 'Revisa las partes del estanque')) s.end = false; return true; }
      return false;
    },
    peek: G => { const it = G.item, s = G.s, n = lcm(it.p, it.q), b = G.box, plus = { x: b.x + b.w - 40, y: b.y, w: 40, h: b.h }, minus = { x: b.x, y: b.y, w: 40, h: b.h }; const steps = s.n === n ? [] : Array(Math.abs(n - s.n)).fill(n > s.n ? plus : minus); return { solve: [...steps, ...Array(hoursOf(it) - (s.n === n ? s.h : 0)).fill(G.btn[0]), G.btn[1]], wrong: G.btn[1] }; },
  });
})();
;
//#archivo js/games/bote-corriente.js
// El bote y la corriente (Álgebra, sistemas de ecuaciones; juego dinámico de alg-101; spec
// 2026-11-21-dinamicos-mundos-altos): el bote de Caro. Río abajo la corriente suma (v + c) y río arriba resta (v − c).
// Se conocen las dos velocidades. Se elige la corriente c con − y + (o arrastrando); el juego despeja el bote de la
// primera pista, v = (río abajo) − c, y lo muestra: eso es sustituir. Al «Zarpar» el bote sube contra la corriente y se
// ve si llega a la bandera de la segunda pista. La velocidad río arriba no se muestra antes: hay que pensarla.
// params = { rounds: [{ title, items: [{ down, up }] }], lives? }   state = { done: [n] }

GAMES['bote-corriente'] = (() => {
  const cOf = it => (it.down - it.up) / 2;
  return questGame({
    aspect: 1.25,
    init: () => ({ c: 0 }),
    ok: (s, it) => it.down - 2 * s.c === it.up,
    answer: it => ({ c: cOf(it) }),
    solution: it => `$v + c = ${it.down}$, $v - c = ${it.up}$: bote ${it.down - cOf(it)}, corriente ${cOf(it)}`,
    prompt: it => `Río abajo va a ${it.down} y río arriba a ${it.up}`,
    foot: () => 'Elige la corriente: el bote sale de la primera pista',
    no: (it, s) => `Río arriba irías a ${it.down - 2 * s.c}, no a ${it.up}: ${it.down - 2 * s.c > it.up ? 'falta corriente' : 'sobra corriente'}`,
    layout(G) {
      const y = G.bottom - 42; G.box = { x: 12, y, w: 160, h: 34 }; G.btn = { x: G.W - 12 - 120, y: y - 2, w: 120, h: 38 };
      G.track = { x0: 30, x1: G.W - 30, y: y - 40 }; G.river = { y: G.top + 10, h: G.track.y - G.top - 46 };
    },
    draw(G) {
      const { p, C, W, s, item: it } = G, r = G.river, v = it.down - s.c, L = W - 60, sc = L / it.down, y1 = r.y + r.h * 0.3, y2 = r.y + r.h * 0.72;
      p.noStroke(); p.fill(shade(C.sky, 0.55)); p.rect(12, r.y, W - 24, r.h, 12);
      const arrow = (y, len, col, txt) => { p.stroke(col); p.strokeWeight(5); p.line(30, y, 30 + len, y); p.noStroke(); p.fill(col); p.triangle(30 + len, y - 7, 30 + len + 11, y, 30 + len, y + 7); p.fill(C.cream); p.textStyle(p.BOLD); p.textAlign(p.LEFT, p.CENTER); fitText(p, txt, 34, y - 14, W - 70, 12); };
      arrow(y1, it.down * sc - 11, C.mint, `río abajo: v + c = ${v} + ${s.c} = ${it.down}`);
      // Río arriba: solo se ve la bandera; la flecha del bote aparece al acertar.
      const fx = 30 + it.up * sc; p.stroke(C.cream); p.strokeWeight(2); p.line(fx, y2 - 20, fx, y2 + 12); p.noStroke(); p.fill(C.sun); p.triangle(fx, y2 - 20, fx + 13, y2 - 14, fx, y2 - 8);
      if (G.solved) arrow(y2, it.up * sc - 11, C.coral, `río arriba: v − c = ${v} − ${s.c} = ${it.up}`);
      else { p.noStroke(); p.fill(C.cream); p.textStyle(p.BOLD); p.textAlign(p.LEFT, p.CENTER); fitText(p, `río arriba: v − c = ${it.up}`, 34, y2 - 14, W - 70, 12); }
      p.noStroke(); p.fill(G.solved ? C.ok : C.ink); p.textStyle(p.BOLD); p.textAlign(p.CENTER, p.CENTER);
      fitText(p, `corriente c = ${s.c}  ·  bote v = ${it.down} − ${s.c} = ${v}`, W / 2, G.track.y, W - 20, 14);
      drawStepper(p, C, G.box, s.c, 'corriente', C.Z);
      drawBtn(p, C, G.btn, 'Zarpar', G.solved, G.solved ? C.ok : C.coral);
    },
    press(G, x, y) {
      const d = stepHit(G.box, x, y);
      if (d) { G.s.c = Math.max(0, Math.min(Math.floor(G.item.down / 2), G.s.c + d)); G.api.sfx?.tap?.(); return true; }
      if (hitBox(G.btn, x, y)) { G.submit(); return true; }
      return false;
    },
    peek: G => { const b = G.box, n = cOf(G.item) - G.s.c; return { solve: [...Array(Math.abs(n)).fill(n > 0 ? { x: b.x + b.w - 40, y: b.y, w: 40, h: b.h } : { x: b.x, y: b.y, w: 40, h: b.h }), G.btn], wrong: n ? G.btn : null }; },
  });
})();
;
//#archivo js/games/cruce-curvas.js
// El cruce de las curvas (Álgebra, sistemas no lineales; juego dinámico de alg-102; spec
// 2026-11-21-dinamicos-mundos-altos): la orilla curva y = x² y un puente recto y = mx + b están tapados por la niebla
// del río. Con ◀ ▶ se mueve una mira por el eje x: en cada x se ven las dos alturas, la de la orilla y la del puente.
// Donde son iguales, las curvas se cortan: ahí se toca «Marcar». Cuando están todos los cruces, «Listo». Puede haber
// dos cruces, uno solo (el puente apenas toca la orilla) o ninguno.
// params = { rounds: [{ title, items: [{ m, b }] }], lives? }   (cruces enteros entre −3 y 3)   state = { done: [n] }

GAMES['cruce-curvas'] = (() => {
  const line = it => `${it.m === 0 ? '' : `${it.m === 1 ? '' : it.m === -1 ? '-' : it.m}x`}${it.b ? `${it.b < 0 ? ' - ' : it.m ? ' + ' : ''}${Math.abs(it.b)}` : it.m ? '' : '0'}`;
  const cuts = it => [-3, -2, -1, 0, 1, 2, 3].filter(x => x * x === it.m * x + it.b);
  return questGame({
    aspect: 1.35,
    init: () => ({ x: 0, marks: [], end: false }),
    ok: (s, it) => !!s.end && [...s.marks].sort((a, b) => a - b).join() === cuts(it).join(),
    answer: it => ({ x: 0, marks: cuts(it), end: true }),
    solution: it => `$x^2 = ${line(it)}$: ${cuts(it).length ? cuts(it).map(x => `(${negTxt(x)}, ${x * x})`).join(' y ') : 'no se cortan'}`,
    prompt: it => `Orilla $y = x^2$ y puente $y = ${line(it)}$: ¿dónde se cortan?`,
    foot: (it, s) => `Cruces marcados: ${s.marks.length}`,
    layout(G) {
      const w = (G.W - 24 - 3 * 8) / 4, y = G.bottom - 42; G.btn = [0, 1, 2, 3].map(i => ({ x: 12 + i * (w + 8), y, w, h: 36 }));
      const top = G.top + 6, h = y - top - 40; G.X = x => 30 + (x + 3) * (G.W - 60) / 6; G.Y = v => top + h - 6 - Math.max(-1, Math.min(10, v)) * (h - 12) / 11; G.ax = top + h + 8;
    },
    draw(G) {
      const { p, C, W, s, item: it } = G, hx = G.X(s.x), yo = s.x * s.x, yp = it.m * s.x + it.b;
      p.stroke(C.ink); p.strokeWeight(2); p.line(20, G.Y(0), W - 20, G.Y(0));
      for (let x = -3; x <= 3; x++) { p.stroke(C.line); p.strokeWeight(1); p.line(G.X(x), G.Y(10), G.X(x), G.Y(-1)); p.noStroke(); p.fill(x === s.x ? C.N : C.mute); p.textStyle(p.BOLD); p.textSize(11); p.textAlign(p.CENTER, p.CENTER); p.text(negTxt(x), G.X(x), G.ax); }
      if (G.solved) {   // al acertar se despeja la niebla
        p.noFill(); p.stroke(C.sky); p.strokeWeight(3); p.beginShape(); for (let x = -3; x <= 3.001; x += 0.1) p.vertex(G.X(x), G.Y(x * x)); p.endShape();
        // El puente, recortado al cuadro (si se recortara solo la altura, la recta se torcería).
        p.stroke(C.coral); p.beginShape(); for (let x = -3; x <= 3.001; x += 0.05) { const v = it.m * x + it.b; if (v >= -1 && v <= 10) p.vertex(G.X(x), G.Y(v)); } p.endShape();
      }
      for (const x of s.marks) { p.noStroke(); p.fill(G.solved ? C.ok : C.sun); p.circle(G.X(x), G.Y(x * x), 16); }
      // La mira: las dos alturas en el x actual.
      p.stroke(C.N); p.strokeWeight(1.5); p.drawingContext.setLineDash([4, 4]); p.line(hx, G.Y(10), hx, G.Y(-1)); p.drawingContext.setLineDash([]);
      drawDot(p, C, hx, G.Y(yo), 10, C.sky); drawDot(p, C, hx, G.Y(yp), 10, C.coral);
      p.noStroke(); p.textStyle(p.BOLD); p.textAlign(p.CENTER, p.CENTER);
      p.fill(C.Z); fitText(p, `orilla: ${yo}`, W * 0.27, G.top + 12, W / 2 - 16, 13); p.fill(C.I); fitText(p, `puente: ${negTxt(yp)}`, W * 0.73, G.top + 12, W / 2 - 16, 13);
      drawBtn(p, C, G.btn[0], '◀', false, C.cream); drawBtn(p, C, G.btn[1], '▶', false, C.cream); drawBtn(p, C, G.btn[2], 'Marcar', false, C.sun); drawBtn(p, C, G.btn[3], 'Listo', G.solved, G.solved ? C.ok : C.coral);
    },
    press(G, x, y) {
      const s = G.s, it = G.item, i = G.btn.findIndex(b => hitBox(b, x, y));
      if (i < 0) return false;
      if (i < 2) { s.x = Math.max(-3, Math.min(3, s.x + (i ? 1 : -1))); G.api.sfx?.tap?.(); return true; }
      if (i === 2) {
        if (s.x * s.x !== it.m * s.x + it.b) { G.bad('Aquí las dos alturas no son iguales'); return true; }
        if (!s.marks.includes(s.x)) s.marks.push(s.x);
        G.api.sfx?.tap?.(); return true;
      }
      s.end = true; if (!G.submit(cuts(it).length ? 'Falta marcar un cruce' : 'Revisa: no hay ningún cruce')) s.end = false;
      return true;
    },
    peek: G => { const it = G.item, s = G.s, seq = []; let x = s.x; for (const c of cuts(it).filter(c => !s.marks.includes(c))) { while (x < c) { seq.push(G.btn[1]); x++; } while (x > c) { seq.push(G.btn[0]); x--; } seq.push(G.btn[2]); } return { solve: [...seq, G.btn[3]], wrong: cuts(it).length > s.marks.length ? G.btn[3] : null }; },
  });
})();
;
//#archivo js/games/lirios-laguna.js
// Los lirios de la laguna (Álgebra, función exponencial; juego dinámico de alg-71; spec
// 2026-11-21-dinamicos-mundos-altos): como en el video, los lirios se duplican cada día y un día dado cubren toda la
// laguna. La pregunta va hacia atrás: ¿qué día estaba medio llena, o a la cuarta parte, o con tantos lirios? Con
// «◀ día» y «día ▶» se mueve el calendario y la laguna se dibuja como estaba ese día; con «Este día» se responde.
// La sorpresa del video: la mitad no está a medio camino, sino un solo día antes.
// params = { rounds: [{ title, items: [{ full, ask: 'half' | 'quarter' | 'eighth' | número de lirios }] }], lives? }
// state = { done: [n] }      (el día `full` hay 2^full lirios y la laguna está llena)

GAMES['lirios-laguna'] = (() => {
  const back = { half: 1, quarter: 2, eighth: 3 };
  const dayOf = it => (typeof it.ask === 'number' ? Math.round(Math.log2(it.ask)) : it.full - back[it.ask]);
  const askTxt = it => (typeof it.ask === 'number' ? `tenía ${it.ask} lirios` : it.ask === 'half' ? 'estaba medio llena' : it.ask === 'quarter' ? 'estaba a la cuarta parte' : 'estaba a la octava parte');
  return questGame({
    aspect: 1.3,
    init: it => ({ day: it.full }),
    ok: (s, it) => s.day === dayOf(it),
    answer: it => ({ day: dayOf(it) }),
    solution: it => `Llena el día ${it.full}: ${askTxt(it)} el día ${dayOf(it)}`,
    prompt: it => `Se llena el día ${it.full}. ¿Qué día ${askTxt(it)}?`,
    foot: () => 'Cada día hacia atrás hay la mitad de lirios',
    no: (it, s) => (s.day < dayOf(it) ? 'Ese día había menos lirios' : 'Ese día había más lirios'),
    layout(G) {
      const w = (G.W - 24 - 2 * 8) / 3, y = G.bottom - 42; G.btn = [0, 1, 2].map(i => ({ x: 12 + i * (w + 8), y, w, h: 36 }));
      const side = Math.min(G.W - 60, y - G.top - 44); G.pond = { x: G.W / 2 - side / 2, y: G.top + 8, s: side };
    },
    draw(G) {
      const { p, C, W, s, item: it } = G, q = G.pond, cells = 64 * 2 ** (s.day - it.full), n = 8, cs = q.s / n;
      p.noStroke(); p.fill(shade(C.sky, 0.55)); p.rect(q.x, q.y, q.s, q.s, 14);
      // 64 casillas: se llenan por columnas (así la mitad y la cuarta parte se ven de un vistazo).
      for (let i = 0; i < 64; i++) {
        const c = Math.floor(i / n), r = i % n, f = Math.max(0, Math.min(1, cells - i));
        if (f <= 0) break;
        p.fill(G.solved ? C.ok : C.mint); p.circle(q.x + c * cs + cs / 2, q.y + r * cs + cs / 2, (cs - 4) * Math.sqrt(f));
      }
      p.noStroke(); p.fill(C.ink); p.textStyle(p.BOLD); p.textAlign(p.CENTER, p.CENTER);
      fitText(p, `Día ${s.day}`, W / 2, q.y + q.s + 14, W - 20, 16);
      drawBtn(p, C, G.btn[0], '◀ día', false, C.cream); drawBtn(p, C, G.btn[1], 'día ▶', false, C.cream); drawBtn(p, C, G.btn[2], 'Este día', G.solved, G.solved ? C.ok : C.coral);
    },
    press(G, x, y) {
      const s = G.s, it = G.item, i = G.btn.findIndex(b => hitBox(b, x, y));
      if (i < 0) return false;
      if (i === 2) { G.submit(); return true; }
      s.day = Math.max(0, Math.min(it.full, s.day + (i ? 1 : -1))); G.api.sfx?.tap?.();
      return true;
    },
    peek: G => { const n = dayOf(G.item) - G.s.day; return { solve: [...Array(Math.abs(n)).fill(G.btn[n > 0 ? 1 : 0]), G.btn[2]], wrong: n ? G.btn[2] : null }; },
  });
})();
;
//#archivo js/games/dos-bancos.js
// Los dos bancos (Álgebra, interés simple y compuesto; juego dinámico de alg-13b; spec
// 2026-11-21-dinamicos-mundos-altos): como Beto en el video, se quiere saber en qué año un ahorro llega a su meta
// (duplicarse, por ejemplo). Se dan el tipo de interés y la tasa, y cómo va el ahorro los tres primeros años. Se toca
// en el calendario el año en que se cree que llega y luego «Correr los años»: el juego hace crecer el ahorro año por
// año y se ve si la apuesta era el primer año en que alcanza la meta. Con interés simple cada año suma lo mismo; con
// compuesto, cada año multiplica.
// params = { rounds: [{ title, items: [{ kind: 'simple' | 'comp', rate (%), goal (factor, p. ej. 2) }] }], lives? }
// state = { done: [n] }

GAMES['dos-bancos'] = (() => {
  const amount = (it, n) => (it.kind === 'simple' ? 1 + (it.rate / 100) * n : (1 + it.rate / 100) ** n);
  const yearOf = it => { for (let n = 1; n <= 16; n++) if (amount(it, n) >= it.goal - 1e-9) return n; return 0; };
  const goalTxt = it => (it.goal === 2 ? 'se duplica' : it.goal === 3 ? 'se triplica' : `llega a ${it.goal} veces`);
  const fmt = v => String(+v.toFixed(2));
  return questGame({
    aspect: 1.3,
    init: () => ({ year: 0 }),
    ok: (s, it) => s.year === yearOf(it),
    answer: it => ({ year: yearOf(it) }),
    solution: it => `${it.kind === 'simple' ? 'Simple' : 'Compuesto'} al ${it.rate} %: ${goalTxt(it)} en el año ${yearOf(it)}`,
    prompt: it => `Interés ${it.kind === 'simple' ? 'simple' : 'compuesto'} del ${it.rate} % anual: ¿en qué año ${goalTxt(it)}?`,
    foot: it => (it.kind === 'simple' ? 'Simple: cada año suma lo mismo' : 'Compuesto: cada año multiplica lo que ya había'),
    no: (it, s) => (s.year < yearOf(it) ? 'Ese año todavía no alcanza la meta' : 'Ya había llegado un año antes'),
    layout(G) {
      G.btn = { x: G.W / 2 - 84, y: G.bottom - 40, w: 168, h: 34 };
      const w = (G.W - 24 - 7 * 6) / 8, y0 = G.btn.y - 92; G.cell = n => ({ x: 12 + ((n - 1) % 8) * (w + 6), y: y0 + Math.floor((n - 1) / 8) * 40, w, h: 34 });
      G.chart = { y: G.top + 8, h: y0 - G.top - 34 };
    },
    draw(G) {
      const { p, C, W, s, item: it } = G, ch = G.chart, shown = G.solved ? yearOf(it) : Math.max(3, s.ran || 0), bw = (W - 40) / 17, top = it.goal * 1.15, Y = v => ch.y + ch.h - (v / top) * ch.h;
      p.stroke(C.coral); p.strokeWeight(2); p.drawingContext.setLineDash([6, 5]); p.line(14, Y(it.goal), W - 14, Y(it.goal)); p.drawingContext.setLineDash([]);
      p.noStroke(); p.fill(C.I); p.textStyle(p.BOLD); p.textSize(10); p.textAlign(p.RIGHT, p.CENTER); p.text(`meta ×${it.goal}`, W - 14, Y(it.goal) - 8);
      for (let n = 0; n <= shown; n++) { const v = Math.min(top, amount(it, n)); p.noStroke(); p.fill(n === shown && G.solved ? C.ok : n ? C.sky : C.mute); p.rect(20 + n * bw, Y(v), bw - 4, ch.y + ch.h - Y(v), 3); }
      p.fill(C.ink); p.textStyle(p.BOLD); p.textAlign(p.CENTER, p.CENTER);
      fitText(p, `Por cada peso: ${[0, 1, 2, 3].map(n => fmt(amount(it, n))).join(' → ')} → …`, W / 2, ch.y + ch.h + 16, W - 20, 13);
      for (let n = 1; n <= 16; n++) drawTile(p, C, G.cell(n), n, { fill: s.year === n ? (G.solved ? C.ok : C.sun) : C.cream, size: 14, r: 8, lift: 2 });
      drawBtn(p, C, G.btn, 'Correr los años', G.solved, G.solved ? C.ok : s.year ? C.coral : C.line);
    },
    press(G, x, y) {
      if (hitBox(G.btn, x, y)) { if (G.s.year) { G.s.ran = G.s.year; G.submit(); } return true; }   // aun fallando, los años corren hasta la apuesta
      for (let n = 1; n <= 16; n++) if (hitBox(G.cell(n), x, y)) { G.s.year = n; G.api.sfx?.tap?.(); return true; }
      return false;
    },
    peek: G => { const n = yearOf(G.item); return { solve: [G.cell(n), G.btn], wrongs: [G.cell(n === 16 ? 15 : n + 1), G.btn] }; },
  });
})();
;
//#archivo js/games/regla-de-calculo.js
// La regla de cálculo (Álgebra, propiedades de los logaritmos; juego dinámico de alg-72; spec
// 2026-11-21-dinamicos-mundos-altos): dos reglas con las potencias de una base puestas a la misma distancia (cada
// paso es un exponente más). Así se multiplicó durante siglos: sumar distancias es multiplicar números, porque el
// logaritmo de un producto es la suma de los logaritmos. Para a × b se corre la regla de arriba con ◀ ▶ hasta que su 1
// quede sobre a, y se toca en la regla de abajo el número que queda debajo de b. Para dividir se hace al revés.
// params = { rounds: [{ title, items: [{ base, a, b, div?: true }] }], lives? }   (a y b potencias de la base)
// state = { done: [n] }      Las reglas muestran base⁰ … base⁶.

GAMES['regla-de-calculo'] = (() => {
  const lg = (it, v) => Math.round(Math.log(v) / Math.log(it.base));
  // Producto: el 1 de arriba sobre a, y se lee debajo de b. Cociente a ÷ b: b de arriba sobre a, y se lee debajo del 1.
  const shiftOf = it => (it.div ? lg(it, it.a) - lg(it, it.b) : lg(it, it.a));
  const pickOf = it => (it.div ? lg(it, it.a) - lg(it, it.b) : lg(it, it.a) + lg(it, it.b));
  return questGame({
    aspect: 1.15,
    init: () => ({ shift: 0, pick: -1 }),
    ok: (s, it) => s.pick === pickOf(it) && (s.shift === shiftOf(it) || (!it.div && s.shift === lg(it, it.b))),
    answer: it => ({ shift: shiftOf(it), pick: pickOf(it) }),
    solution: it => (it.div ? `$${it.a} \\div ${it.b} = ${it.base ** pickOf(it)}$: exponentes ${lg(it, it.a)} − ${lg(it, it.b)} = ${pickOf(it)}` : `$${it.a} \\times ${it.b} = ${it.base ** pickOf(it)}$: exponentes ${lg(it, it.a)} + ${lg(it, it.b)} = ${pickOf(it)}`),
    prompt: it => (it.div ? `Divide con la regla: $${it.a} \\div ${it.b}$` : `Multiplica con la regla: $${it.a} \\times ${it.b}$`),
    foot: it => (it.div ? `Pon el ${it.b} de arriba sobre el ${it.a} y lee debajo del 1` : `Pon el 1 de arriba sobre un factor y lee debajo del otro`),
    no: (it, s) => (s.shift !== shiftOf(it) && !(!it.div && s.shift === lg(it, it.b)) ? 'La regla de arriba no está en su lugar' : 'Lee el número que queda justo debajo'),
    retry: G => { G.s.pick = -1; },
    layout(G) {
      const y = G.bottom - 42; G.btn = [{ x: 12, y, w: 70, h: 36 }, { x: 90, y, w: 70, h: 36 }];
      const step = (G.W - 40) / 7; G.step = step; G.y0 = G.top + (y - G.top) / 2 - 8;
      G.low = k => ({ x: 20 + k * step, y: G.y0 + 4, w: step, h: 44 });
    },
    draw(G) {
      const { p, C, W, s, item: it } = G, st = G.step, y0 = G.y0;
      p.noStroke(); p.fill(C.card); p.stroke(C.line); p.strokeWeight(1.5); p.rect(14, y0 + 2, W - 28, 48, 8);
      for (let k = 0; k <= 6; k++) {
        const b = G.low(k), on = s.pick === k;
        if (on) { p.noStroke(); p.fill(G.solved ? C.ok : C.sun); p.rect(b.x + 2, b.y, b.w - 4, b.h - 2, 6); }
        p.stroke(C.ink); p.strokeWeight(2); p.line(b.x + b.w / 2, y0 + 2, b.x + b.w / 2, y0 + 12);
        p.noStroke(); p.fill(on ? inkOn(C.sun, C.ink) : C.ink); p.textStyle(p.BOLD); p.textAlign(p.CENTER, p.CENTER); fitText(p, String(it.base ** k), b.x + b.w / 2, y0 + 26, b.w - 4, 15);
        p.fill(C.mute); p.textSize(9); p.text(k, b.x + b.w / 2, y0 + 62);
      }
      p.fill(C.mute); p.textSize(9); p.textAlign(p.LEFT, p.CENTER); p.text('exponente', 16, y0 + 76);
      // La regla de arriba, corrida `shift` pasos.
      const ux = 14 + s.shift * st;
      p.fill(shade(C.sky, 0.9)); p.noStroke(); p.rect(ux, y0 - 46, W - 28, 46, 8);
      for (let k = 0; k <= 6; k++) {
        const x = ux + 6 + k * st + st / 2; if (x > W - 4) break;
        p.stroke(C.cream); p.strokeWeight(2); p.line(x, y0 - 10, x, y0);
        p.noStroke(); p.fill(C.cream); p.textStyle(p.BOLD); p.textAlign(p.CENTER, p.CENTER); fitText(p, String(it.base ** k), x, y0 - 26, st - 4, 15);
      }
      drawBtn(p, C, G.btn[0], '◀', false, C.cream); drawBtn(p, C, G.btn[1], '▶', false, C.cream);
      p.noStroke(); p.fill(C.mute); p.textStyle(p.NORMAL); p.textAlign(p.LEFT, p.TOP); p.textSize(11); p.text('Corre la regla y toca el resultado abajo', 172, G.btn[0].y + 4, W - 180, 30);   // en caja: en celular angosto va en dos renglones, sin pisar el botón
    },
    press(G, x, y) {
      const s = G.s, i = G.btn.findIndex(b => hitBox(b, x, y));
      if (i >= 0) { s.shift = Math.max(0, Math.min(6, s.shift + (i ? 1 : -1))); s.pick = -1; G.api.sfx?.tap?.(); return true; }
      for (let k = 0; k <= 6; k++) if (hitBox(G.low(k), x, y)) { s.pick = k; G.submit(); return true; }
      return false;
    },
    peek: G => { const it = G.item, n = shiftOf(it) - G.s.shift, b = G.low(pickOf(it)), w = G.low((pickOf(it) + 1) % 7); return { solve: [...Array(Math.abs(n)).fill(G.btn[n > 0 ? 1 : 0]), { x: b.x + b.w / 2 - 2, y: b.y + 20, w: 4, h: 4 }], wrong: { x: w.x + w.w / 2 - 2, y: w.y + 20, w: 4, h: 4 } }; },
  });
})();
;
//#archivo js/games/piedras-selva.js
// Las piedras de la selva (Álgebra, ecuaciones exponenciales y logarítmicas; juego dinámico de alg-73; spec
// 2026-11-21-dinamicos-mundos-altos): la trampa del video. Al resolver una ecuación salen candidatos, y no todos
// sirven: un logaritmo no acepta números negativos ni el cero. En el río hay piedras con los candidatos; para cruzar
// se pisan TODAS las que sí son solución y ninguna de las que no. Pisar una falsa quita una vida y el juego dice por
// qué no sirve.
// params = { rounds: [{ title, items: [{ eq (TeX), stones: [{ x (texto), ok, why? }] }] }], lives? }   state = { done: [n] }

GAMES['piedras-selva'] = (() => {
  const good = it => it.stones.map((q, i) => (q.ok ? i : -1)).filter(i => i >= 0);
  return questGame({
    aspect: 1.15,
    init: () => ({ on: [] }),
    ok: (s, it) => [...s.on].sort((a, b) => a - b).join() === good(it).join(),
    answer: it => ({ on: good(it) }),
    solution: it => `$${it.eq}$: ${good(it).map(i => `x = ${it.stones[i].x}`).join(' y ')}`,
    prompt: it => `$${it.eq}$`,
    foot: (it, s) => `Pisa todas las soluciones que sí sirven · llevas ${s.on.length}`,
    layout(G) {
      const n = G.item.stones.length, w = Math.min(74, (G.W - 24 - (n - 1) * 10) / n), x0 = G.W / 2 - (n * w + (n - 1) * 10) / 2, mid = G.top + (G.bottom - G.top) / 2;
      G.stone = i => ({ x: x0 + i * (w + 10), y: mid - 26 + (i % 2 ? 22 : -22), w, h: 52 }); G.mid = mid;
    },
    draw(G) {
      const { p, C, W, s, item: it } = G;
      p.noStroke(); p.fill(shade(C.sky, 0.55)); p.rect(12, G.mid - 70, W - 24, 140, 16);
      it.stones.forEach((q, i) => {
        const b = G.stone(i), on = s.on.includes(i);
        p.noStroke(); p.fill(shade(on ? (G.solved ? C.ok : C.mint) : C.cream, 0.74)); p.ellipse(b.x + b.w / 2, b.y + b.h / 2 + 4, b.w, b.h);
        p.fill(on ? (G.solved ? C.ok : C.mint) : C.cream); p.ellipse(b.x + b.w / 2, b.y + b.h / 2, b.w, b.h);
        p.fill(inkOn(on ? C.mint : C.cream, C.ink)); p.textStyle(p.BOLD); p.textAlign(p.CENTER, p.CENTER); fitText(p, `$x = ${q.x}$`, b.x + b.w / 2, b.y + b.h / 2, b.w - 10, 15, 30);
      });
    },
    press(G, x, y) {
      const it = G.item, s = G.s, i = it.stones.findIndex((_, k) => hitBox(G.stone(k), x, y));
      if (i < 0 || s.on.includes(i)) return i >= 0;
      if (!it.stones[i].ok) { G.bad(it.stones[i].why || 'Reemplázala en la ecuación: no la cumple'); return true; }
      s.on.push(i); G.api.sfx?.tap?.();
      if (s.on.length === good(it).length) G.good('¡Cruzaste el río!');
      return true;
    },
    peek: G => { const it = G.item, bad = it.stones.findIndex(q => !q.ok); return { solve: good(it).filter(i => !G.s.on.includes(i)).map(i => G.stone(i)), wrong: bad >= 0 ? G.stone(bad) : null }; },
  });
})();
;
//#archivo js/games/quita-vueltas.js
// Quita vueltas (Trigonometría, trig-41a): un ángulo grande o negativo y su coterminal. El lado terminal no se mueve al quitar o poner
// vueltas completas. item = { deg, lo? (0), rad? }
GAMES['quita-vueltas'] = (() => {
  const fmt = (it, d) => (it.rad ? `$${TK.piTex(d / 15, 12)}$` : `${TK.minusTxt(d)}°`);
  const lo = it => it.lo ?? 0, need = it => -Math.floor((it.deg - lo(it)) / 360);
  return questGame({
    aspect: 1.3,
    init: () => ({ k: 0 }),
    ok: (s, it) => { const d = it.deg + 360 * s.k; return d >= lo(it) && d < lo(it) + 360; },
    answer: it => ({ k: need(it) }),
    solution: it => `${fmt(it, it.deg)} → ${fmt(it, it.deg + 360 * need(it))}`,
    prompt: it => `Quita o pon vueltas hasta dejar ${fmt(it, it.deg)} entre ${fmt(it, lo(it))} y ${fmt(it, lo(it) + 360)}`,
    foot: () => 'El lado terminal no se mueve: todos esos ángulos son coterminales',
    layout(G) { G.btn = TK.row(G, 3); const h = G.btn[0].y - G.top - 34; G.R = Math.min(G.W * 0.3, h / 2 - 4); G.cx = G.W / 2; G.cy = G.top + 8 + h / 2; },
    draw(G) {
      const { p, C, s, item: it, cx, cy, R } = G, d = it.deg + 360 * s.k, [tx, ty] = TK.at(cx, cy, R, d);
      TK.ring(p, C, cx, cy, R);
      // La espiral cuenta las vueltas; el lado terminal queda quieto.
      p.noFill(); p.stroke(G.solved ? C.ok : C.coral); p.strokeWeight(3); p.beginShape();
      const ds = TK.glide(G, 'd', d, 6), n = Math.max(8, Math.ceil(Math.abs(ds) / 6));
      for (let i = 0; i <= n; i++) { const a = ds * i / n, r = R * 0.2 + Math.min(R * 0.62, Math.abs(a) / 360 * R * 0.17); p.vertex(...TK.at(cx, cy, r, a)); }
      p.endShape();
      p.stroke(C.sky); p.strokeWeight(4); p.line(cx, cy, tx, ty); drawDot(p, C, tx, ty, 11, C.sky);
      TK.label(p, C, G.solved ? fmt(it, d) : `${fmt(it, it.deg)} ${s.k < 0 ? '−' : '+'} ${Math.abs(s.k)} ${Math.abs(s.k) === 1 ? 'vuelta' : 'vueltas'}`, cx, cy + R + 20, G.solved ? C.ok : C.ink, 17, 220);
      drawBtn(p, C, G.btn[0], '− 1 vuelta', false, C.cream); drawBtn(p, C, G.btn[1], '+ 1 vuelta', false, C.cream); drawBtn(p, C, G.btn[2], 'Listo', G.solved, G.solved ? C.ok : C.coral);
    },
    press(G, x, y) {
      const s = G.s, i = G.btn.findIndex(b => hitBox(b, x, y));
      if (i < 0) return false;
      if (i === 2) { G.submit('Todavía no está en ese intervalo'); return true; }
      const k = s.k + (i ? 1 : -1);
      if (Math.abs(G.item.deg + 360 * k) <= 2160) { s.k = k; G.api.sfx?.tap?.(); }
      return true;
    },
    peek: G => { const n = need(G.item) - G.s.k; return { solve: [...Array(Math.abs(n)).fill(G.btn[n > 0 ? 1 : 0]), G.btn[2]], wrong: n ? G.btn[2] : null }; },
  });
})();
