  const ALL = ['sen', 'cos', 'tan', 'csc', 'sec', 'cot'], IDX = { op: 0, ady: 1, hip: 2 };
  const fn = it => RATIO[`${it.want}/${it.known}`], res = it => Math.round(it.val * TK.F[fn(it)](TK.rad(it.deg)) * 10) / 10;
