          if (s.up && s.dn) {
            const f = it.f[s.cur], good = s.up === key(TOK[f][0]) && s.dn === key(TOK[f][1]);
            if (good) { s.open[s.cur] = true; s.cur = null; G.api.sfx?.tap?.(); } else { s.up = s.dn = null; G.bad('Esa fracción no es esa función: repasa su definición'); }
          }
