      for (const m of s.marks) { const t = tip(m); p.stroke(C.ok); p.strokeWeight(3); p.line(...P, ...t); drawDot(p, C, t[0], t[1], 9, C.ok); TK.label(p, C, `${m}°`, t[0], t[1] - 14, C.ok, 12, 40); }
