    op: { name: 'su opuesto $-z$', rule: 'El opuesto queda a media vuelta: ángulo + 180°', to: it => [it.r, it.deg + 180] },
    i: { name: '$i \\cdot z$', rule: 'Multiplicar por i es un cuarto de vuelta: ángulo + 90°', to: it => [it.r, it.deg + 90] },
